const V7_ASSIGNMENTS={"engr10": [{"id": "engr-units-est", "title": "Practice Set · Units, Estimates & Sanity Checks", "due": "Aug 28 at 11:59 PM", "points": 20, "group": "Homework", "kind": "worksheet", "questions": [{"type": "text", "q": "1. Convert 18 ft to inches."}, {"type": "text", "q": "2. A slab is 12 ft × 20 ft × 4 in. Estimate its volume in cubic feet."}, {"type": "textarea", "q": "3. A cost estimate is $48,000 with ±20% early-stage uncertainty. Give a reasonable range and explain why reporting only $48,000 can mislead."}, {"type": "textarea", "q": "4. Give one quick order-of-magnitude check you could use before trusting a calculated answer."}], "instructions": "Show units on every numerical step. The goal is not speed; it is developing habits that catch impossible answers before they travel into a report.", "completed": true, "score": 19, "submittedAt": "Aug 28 at 8:41 PM", "feedback": "Strong dimensional reasoning. On #3, you correctly treated the uncertainty as a range instead of fake precision.", "sampleAnswers": ["216 in", "80 ft³", "About $38,400–$57,600. Reporting one exact value hides uncertainty that matters for decisions.", "Compare against a simple benchmark or rough mental estimate before accepting the detailed result."], "rubric": [["Units and conversions", 6, "Units carried through correctly"], ["Reasonableness", 5, "Checks magnitude and plausibility"], ["Uncertainty", 5, "Explains range and communication"], ["Presentation", 4, "Work is readable and organized"]], "context": "Engineers lose credibility quickly when units or scale are wrong. This set builds the small checking habits used throughout statics, estimating, and design.", "steps": ["Write the given values with units.", "Convert dimensions before multiplying.", "Estimate the expected magnitude.", "Calculate.", "Compare the result to the estimate and explain discrepancies."], "supportResources": ["mitStatics"], "reviewLectureId": "engr-l1b"}, {"id": "engr-w1-check", "title": "Week 1 Checkpoint · Problem Framing & Units", "due": "Aug 30 at 11:59 PM", "points": 15, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "Which statement is most solution-neutral?", "options": ["Install a steel canopy.", "Students need reliable afternoon shade while preserving accessible circulation.", "Buy four umbrellas.", "Pour new footings."], "answer": 1}, {"type": "mc", "q": "Which is a constraint?", "options": ["Minimize maintenance.", "Improve comfort.", "Total installed cost must not exceed $40,000.", "Prefer an attractive finish."], "answer": 2}, {"type": "mc", "q": "3.5 ft equals:", "options": ["35 in", "42 in", "48 in", "350 in"], "answer": 1}, {"type": "mc", "q": "A result of 2,400 ft for a classroom width should first trigger:", "options": ["Immediate submission", "A reasonableness/unit check", "A new color scheme", "A higher precision calculator"], "answer": 1}, {"type": "mc", "q": "An assumption register is useful because it:", "options": ["Makes unknowns disappear", "Tracks uncertain inputs and their consequences", "Replaces field measurements", "Guarantees code compliance"], "answer": 1}], "completed": true, "score": 15, "submittedAt": "Aug 30 at 9:12 PM", "feedback": "Excellent. Your Week 1 concepts are solid.", "context": "This checkpoint mixes problem framing with quantitative hygiene because both are part of professional judgment.", "supportResources": ["designVideo"], "reviewLectureId": "engr-l1", "timeLimit": 20, "sampleAnswers": ["1", "2", "1", "1", "1"]}, {"id": "engr-matrix-lab", "title": "Studio · Decision Matrix + Sensitivity Analysis", "due": "Sep 3 at 11:59 PM", "points": 25, "group": "Projects", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Define three criteria for choosing between two fictional campus shade concepts. Explain why each criterion matters."}, {"type": "textarea", "q": "2. Assign weights totaling 100% and justify the largest weight."}, {"type": "textarea", "q": "3. Score Concept A and Concept B from 1–5. Show the weighted totals."}, {"type": "textarea", "q": "4. Increase the cost weight by 10 percentage points and reduce another weight accordingly. Does the recommendation change?"}, {"type": "textarea", "q": "5. In 100–150 words, explain what the sensitivity result means for the design team."}], "instructions": "Use a transparent scoring model. The point is not to force a winner—it is to expose assumptions and see whether the recommendation is robust.", "completed": true, "score": 24, "submittedAt": "Sep 3 at 10:18 PM", "feedback": "Excellent sensitivity explanation. You recognized that a near-tie means the team should gather better cost/maintenance evidence before treating the ranking as final.", "sampleAnswers": ["Safety/accessibility, lifecycle cost, shade performance.", "40%, 30%, 30%; safety/accessibility is largest because an unusable or unsafe concept is not acceptable.", "A: 4.2/5; B: 4.0/5 after weighted scoring.", "With cost at 40%, B becomes 4.05 and A 4.0, so the ranking flips.", "The original recommendation is sensitive. A small priority change changes the winner, so the team should not present A as overwhelmingly superior."], "rubric": [["Criteria", 5, "Specific and decision-relevant"], ["Weights", 5, "Total 100% and justified"], ["Scoring", 6, "Consistent scale and arithmetic"], ["Sensitivity", 5, "Tests a meaningful change"], ["Interpretation", 4, "Explains implications honestly"]], "context": "Decision tools are strongest when they help you ask better questions. A sensitivity test tells you whether the choice is stable or fragile.", "steps": ["Define criteria before looking at scores.", "Choose and justify weights.", "Score both concepts on the same scale.", "Calculate weighted totals.", "Perturb an important assumption.", "Explain whether the conclusion is robust."], "workedExample": "Example: If A=4.10 and B=4.02, do not call that a landslide. Test the weights that are both important and uncertain.", "supportResources": ["designVideo"], "reviewLectureId": "engr-l2"}, {"id": "engr-w2-check", "title": "Week 2 Quiz · Design Decisions, Ethics & Risk", "due": "Sep 6 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A decision matrix should primarily:", "options": ["Replace engineering judgment", "Document criteria, weights, evidence and trade-offs", "Make every concept score equally", "Eliminate uncertainty"], "answer": 1}, {"type": "mc", "q": "If a 5% weight change flips the preferred concept, the result is:", "options": ["Insensitive", "Sensitive", "Invalid by definition", "Automatically unethical"], "answer": 1}, {"type": "mc", "q": "Best way to communicate an uncertain early cost estimate:", "options": ["Give one exact number only", "State the estimate, assumptions and uncertainty range", "Hide the estimate", "Round to the nearest dollar"], "answer": 1}, {"type": "mc", "q": "Public welfare matters in engineering because:", "options": ["Technical choices can affect people beyond the immediate client", "Only lawyers care about it", "It applies only to bridges", "It is optional when schedule is tight"], "answer": 0}, {"type": "mc", "q": "A high-severity, low-probability hazard should generally be:", "options": ["Ignored", "Identified and evaluated rather than dismissed", "Converted into a color preference", "Removed from the report"], "answer": 1}, {"type": "mc", "q": "A concept that violates a true project constraint should:", "options": ["Win if it has the highest aesthetic score", "Be treated as infeasible unless the constraint changes", "Receive bonus points", "Skip review"], "answer": 1}], "completed": true, "score": 19, "submittedAt": "Sep 6 at 7:39 PM", "feedback": "Very strong. Review the difference between a preference and a true constraint.", "context": "This quiz checks whether you can reason about decisions, not just memorize vocabulary.", "supportResources": ["designVideo"], "reviewLectureId": "engr-l2b", "timeLimit": 25, "sampleAnswers": ["1", "1", "1", "0", "1", "1"]}, {"id": "engr-reactions-hw", "title": "HW 4 · Support Reactions & Moments", "due": "Sep 12 at 11:59 PM", "points": 30, "group": "Homework", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. A 12-ft simply supported beam carries an 800-lb point load 3 ft from support A. Find Ay and By. Show ΣM_A=0 and ΣFy=0."}, {"type": "textarea", "q": "2. A 16-ft beam carries a 1,200-lb point load 10 ft from A. Find the reactions and explain which support should carry more load and why."}, {"type": "textarea", "q": "3. A 6-ft cantilever shelf carries a 150-lb downward load at its free end. What reaction force and reaction moment are needed at the fixed support?"}, {"type": "textarea", "q": "4. Describe one sign-convention mistake that could happen in a moment equation and how you would catch it."}, {"type": "textarea", "q": "5. Explain why taking moments about a support is often a smart first equation."}], "instructions": "Draw or describe an FBD for each system before writing equations. Label all distances and units. If you solve correctly but cannot explain whether the result makes physical sense, the problem is not finished.", "completed": false, "rubric": [["FBD/model", 6, "Correct external forces and geometry"], ["Moment equations", 8, "Correct distances and signs"], ["Force equilibrium", 6, "Correct reactions"], ["Reasonableness", 5, "Interprets load location and reaction sizes"], ["Communication", 5, "Clear units and explanation"]], "context": "This is the bridge from “I understand what a moment is” to “I can use equilibrium to solve a real static model.”", "steps": ["Sketch the beam and supports.", "Replace supports with reactions.", "Choose a sign convention.", "Take moments about a convenient point.", "Use force equilibrium.", "Check that reactions sum to total load and make sense spatially."], "workedExample": "For an 800-lb load 3 ft from A on a 12-ft beam: By(12)=800(3), so By=200 lb; Ay=600 lb. The closer support carries more.", "supportResources": ["openstaxEquilibrium", "openstaxTorque"], "reviewLectureId": "engr-l3b"}, {"id": "engr-statics-quiz", "title": "Quiz 3 · FBDs, Reactions & Moments", "due": "Sep 11 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A 10-ft simply supported beam with a 1,000-lb midspan load has reactions:", "options": ["100/900 lb", "500/500 lb", "1,000/1,000 lb", "0/1,000 lb"], "answer": 1}, {"type": "mc", "q": "A pin support in a 2D idealization supplies:", "options": ["One reaction", "Two force components", "A moment only", "No reactions"], "answer": 1}, {"type": "mc", "q": "Moment magnitude from a 100-lb perpendicular force 4 ft from a pivot is:", "options": ["25 lb-ft", "100 lb-ft", "400 lb-ft", "4 lb-ft"], "answer": 2}, {"type": "mc", "q": "Why choose a pivot through an unknown reaction?", "options": ["It can eliminate that reaction from the moment equation", "It changes gravity", "It makes units unnecessary", "It doubles the force"], "answer": 0}, {"type": "mc", "q": "On the FBD of a book resting on a table, which belongs?", "options": ["The force the book exerts on the table", "Normal force from table on book", "Internal molecular forces only", "The table’s weight"], "answer": 1}, {"type": "mc", "q": "If reactions sum to 700 lb upward while applied vertical load is 900 lb downward in static equilibrium:", "options": ["The model/equations are incomplete or wrong", "The beam accelerates by definition", "The answer is always fine", "Units do not matter"], "answer": 0}], "completed": false, "context": "Short conceptual check before the larger Week 3 unit test.", "supportResources": ["openstaxFbd", "mitStatics"], "reviewLectureId": "engr-l3b", "timeLimit": 25}, {"id": "engr-unit1-test", "title": "Unit Test 1 · Engineering Reasoning + Intro Statics", "due": "Sep 13 at 11:59 PM", "points": 40, "group": "Exams", "kind": "quiz", "questions": [{"type": "mc", "q": "A criterion differs from a constraint because a criterion:", "options": ["Is always a legal rule", "Helps compare alternatives while a constraint is a hard limit", "Cannot be weighted", "Must be numerical"], "answer": 1}, {"type": "mc", "q": "A sensitivity analysis asks:", "options": ["What if key assumptions/weights change?", "Who drew the diagram?", "What font should be used?", "How to remove all uncertainty?"], "answer": 0}, {"type": "mc", "q": "Best evidence of sound uncertainty communication:", "options": ["A precise number with no source", "An estimate with assumptions, source and range", "No estimate at all", "A rounded guess called exact"], "answer": 1}, {"type": "mc", "q": "A load path should ultimately transfer structural load to:", "options": ["A spreadsheet", "The supporting ground/soil", "The roof membrane only", "A drawing title block"], "answer": 1}, {"type": "mc", "q": "A roller on a horizontal surface usually supplies:", "options": ["Vertical reaction only", "Horizontal and vertical reactions", "A resisting moment only", "Three force components"], "answer": 0}, {"type": "mc", "q": "For planar equilibrium, the standard equations are:", "options": ["ΣFx=0, ΣFy=0, ΣM=0", "v=u+at only", "E=mc²", "P=IV only"], "answer": 0}, {"type": "mc", "q": "A 600-lb load is centered on a symmetric simply supported beam. Each vertical reaction is:", "options": ["150 lb", "300 lb", "600 lb", "1,200 lb"], "answer": 1}, {"type": "mc", "q": "A 200-lb perpendicular force 2.5 ft from a pivot creates moment magnitude:", "options": ["80 lb-ft", "200 lb-ft", "500 lb-ft", "2.5 lb-ft"], "answer": 2}, {"type": "mc", "q": "If a result violates a true constraint, the concept is:", "options": ["Still automatically preferred", "Infeasible unless the constraint changes", "Guaranteed safer", "Exempt from review"], "answer": 1}, {"type": "mc", "q": "A professional recommendation should include:", "options": ["Only the final answer", "Reasoning, evidence, assumptions and relevant uncertainty", "No alternatives", "Only raw calculations"], "answer": 1}], "completed": false, "context": "Cumulative Week 1–3 assessment. Use it to identify what to relearn, not just to chase a score.", "supportResources": ["mitStatics", "designVideo"], "reviewLectureId": "engr-l3c", "timeLimit": 45}], "math1a": [{"id": "math-limits-check", "title": "Quiz · Limits from Graphs & Tables", "due": "Aug 29 at 11:59 PM", "points": 15, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "If left and right limits approach different numbers, the two-sided limit:", "options": ["Equals their average", "Does not exist", "Always equals f(a)", "Is zero"], "answer": 1}, {"type": "mc", "q": "lim x→3 (x²−9)/(x−3) equals:", "options": ["0", "3", "6", "Does not exist"], "answer": 2}, {"type": "mc", "q": "A removable hole can exist while:", "options": ["The limit still exists", "No nearby values exist", "Every derivative is zero", "The function must be continuous"], "answer": 0}, {"type": "mc", "q": "Direct substitution giving 0/0 means:", "options": ["The limit is zero", "More analysis/simplification is needed", "The limit never exists", "The function is linear"], "answer": 1}], "completed": true, "score": 15, "submittedAt": "Aug 29 at 8:03 PM", "feedback": "Perfect checkpoint.", "context": "Use this to distinguish the behavior of a function near a point from its value at the point.", "reviewLectureId": "math-l1b", "timeLimit": 20, "sampleAnswers": ["1", "2", "0", "1"]}, {"id": "math-cont-hw", "title": "Homework · Continuity & Piecewise Functions", "due": "Sep 4 at 11:59 PM", "points": 25, "group": "Homework", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. State the three conditions for continuity at x=a."}, {"type": "textarea", "q": "2. Find k so f(x)={x+2 for x<1; kx for x≥1} is continuous at x=1."}, {"type": "textarea", "q": "3. Give an example of a function with a removable discontinuity and explain how it could be repaired."}, {"type": "textarea", "q": "4. Explain the Intermediate Value Theorem in your own words and what assumptions it needs."}], "instructions": "Write complete reasoning, not only final numbers. For piecewise continuity, compare the left-hand limit, right-hand limit, and actual function value.", "completed": true, "score": 23, "submittedAt": "Sep 4 at 10:21 PM", "feedback": "Good logic. Your IVT explanation was correct; be explicit that continuity is required on the interval.", "sampleAnswers": ["f(a) exists; lim x→a f(x) exists; the limit equals f(a).", "Left side gives 3; right side gives k, so k=3.", "For (x²−1)/(x−1), x≠1, there is a hole at x=1 but the limit is 2; define f(1)=2 to repair it.", "If a function is continuous on [a,b], it takes every value between f(a) and f(b) somewhere in the interval."], "rubric": [["Continuity conditions", 5, "Complete and correct"], ["Piecewise reasoning", 8, "Matches one-sided values and f(a)"], ["Example", 5, "Valid removable discontinuity"], ["IVT explanation", 7, "Includes continuity and conclusion"]], "context": "Continuity is the logic that lets us trust many graphical and physical arguments. It also prepares you for derivative existence.", "reviewLectureId": "math-l2b"}, {"id": "math-unit-limits", "title": "Unit Check · Limits & Continuity", "due": "Sep 6 at 11:59 PM", "points": 30, "group": "Exams", "kind": "quiz", "questions": [{"type": "mc", "q": "lim x→2 (x²−4)/(x−2)=", "options": ["0", "2", "4", "DNE"], "answer": 2}, {"type": "mc", "q": "A function can have a limit at a even if:", "options": ["f(a) is undefined", "No values exist near a", "Left/right limits differ", "The domain is empty"], "answer": 0}, {"type": "mc", "q": "Continuity at a requires:", "options": ["Only f(a)", "Only the limit", "f(a), limit, and equality", "A horizontal tangent"], "answer": 2}, {"type": "mc", "q": "The IVT requires the function to be:", "options": ["Continuous on the interval", "Differentiable everywhere", "Quadratic", "Positive"], "answer": 0}, {"type": "mc", "q": "A jump discontinuity typically has:", "options": ["Equal one-sided limits", "Different one-sided limits", "No graph", "A derivative of 1"], "answer": 1}, {"type": "mc", "q": "0/0 after substitution is:", "options": ["A final answer", "An indeterminate form inviting more work", "Always infinity", "Always zero"], "answer": 1}], "completed": true, "score": 28, "submittedAt": "Sep 6 at 9:08 PM", "feedback": "Strong work. One missed item involved one-sided limits.", "context": "Cumulative assessment for Weeks 1–2. You can reopen the earlier lectures from Study Center before retrying.", "reviewLectureId": "math-l2b", "timeLimit": 35, "sampleAnswers": ["2", "0", "2", "0", "1", "1"]}, {"id": "math-derivative-rules", "title": "Practice Set · Derivative Rules", "due": "Sep 11 at 11:59 PM", "points": 25, "group": "Homework", "kind": "worksheet", "questions": [{"type": "text", "q": "1. d/dx(5x^4 − 3x^2 + 7) = ?"}, {"type": "text", "q": "2. d/dx[(x²+1)(3x−4)] = ?"}, {"type": "text", "q": "3. d/dx[(2x+1)/(x−3)] = ?"}, {"type": "textarea", "q": "4. Differentiate f(x)=(3x²+1)^4 using the chain rule. Show outer and inner derivatives."}, {"type": "textarea", "q": "5. Explain one way to check whether your derivative is plausible."}], "instructions": "Write the rule you are using next to each step for at least problems 2–4.", "completed": false, "rubric": [["Setup/rule choice", 8, "Correct rule identified"], ["Derivative work", 10, "Accurate differentiation"], ["Explanation/check", 4, "Reasonable verification strategy"], ["Presentation", 3, "Readable algebra"]], "context": "The goal is not memorizing symbols in isolation. Learn to recognize the structure of the expression and choose the rule that matches it.", "steps": ["Identify the outermost operation.", "Choose the rule: power, product, quotient, chain.", "Differentiate carefully.", "Simplify only after the derivative structure is correct.", "Check with dimensions, a graph, or a numerical slope when possible."], "workedExample": "For (x²+1)^3: outer derivative 3u², inner derivative 2x, so f′(x)=3(x²+1)²(2x)=6x(x²+1)².", "supportResources": ["khanDeriv", "mitCalc"], "reviewLectureId": "math-l3b"}, {"id": "math-deriv-quiz", "title": "Quiz · Derivative Meaning & Rules", "due": "Sep 12 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "The derivative of position with respect to time is:", "options": ["Acceleration", "Velocity", "Area", "Mass"], "answer": 1}, {"type": "mc", "q": "d/dx(x^5)=", "options": ["5x^4", "x^4", "5x", "x^6/6"], "answer": 0}, {"type": "mc", "q": "The product rule for uv is:", "options": ["u′v+uv′", "u′v′", "u/v", "uv"], "answer": 0}, {"type": "mc", "q": "d/dx(sin x)=", "options": ["cos x", "−sin x", "tan x", "1"], "answer": 0}, {"type": "mc", "q": "The chain rule is needed most directly for:", "options": ["x²+3x", "(2x+1)^7", "5x", "x+4"], "answer": 1}, {"type": "mc", "q": "A tangent-line slope at x=a is:", "options": ["f(a) only", "f′(a)", "The area under f", "Always zero"], "answer": 1}], "completed": false, "context": "A compact check before the longer Week 3 test.", "supportResources": ["khanDeriv"], "reviewLectureId": "math-l3b", "timeLimit": 25}, {"id": "math-week3-test", "title": "Week 3 Test · Derivatives & Applications", "due": "Sep 13 at 11:59 PM", "points": 40, "group": "Exams", "kind": "quiz", "questions": [{"type": "mc", "q": "Using the limit definition, the derivative represents the limit of:", "options": ["Areas", "Average rates over shrinking intervals", "Function values only", "Integrals"], "answer": 1}, {"type": "mc", "q": "d/dx(3x³−2x)=", "options": ["9x²−2", "3x²−2", "9x−2", "x³"], "answer": 0}, {"type": "mc", "q": "For s(t)=4t², velocity at t=3 is:", "options": ["12", "24", "36", "48"], "answer": 1}, {"type": "mc", "q": "If f′(a)>0, f is locally:", "options": ["Decreasing", "Increasing", "Constant everywhere", "Undefined"], "answer": 1}, {"type": "mc", "q": "The derivative of (x²+1)^3 is:", "options": ["3(x²+1)²", "6x(x²+1)²", "3x²", "6x"], "answer": 1}, {"type": "mc", "q": "A horizontal tangent occurs where:", "options": ["f=0 always", "f′=0 when derivative exists", "x=0 always", "The limit diverges"], "answer": 1}, {"type": "mc", "q": "Units of dV/dt when V is liters and t is minutes are:", "options": ["liters", "minutes", "liters/minute", "minute/liter²"], "answer": 2}, {"type": "mc", "q": "If a numerical derivative is wildly different from nearby secant slopes, you should:", "options": ["Ignore it", "Check algebra/input and scale", "Delete units", "Assume secants are wrong"], "answer": 1}], "completed": false, "context": "This test mixes calculation and interpretation. After submission, use the Study Center to revisit any lecture tied to missed ideas.", "supportResources": ["mitCalc"], "reviewLectureId": "math-l3c", "timeLimit": 50}], "phys4a": [{"id": "phys-kin-quiz", "title": "Quiz · Kinematics & Motion Graphs", "due": "Aug 30 at 11:59 PM", "points": 15, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "Slope of a position-time graph is:", "options": ["Acceleration", "Velocity", "Force", "Energy"], "answer": 1}, {"type": "mc", "q": "Area under a velocity-time graph is:", "options": ["Displacement", "Acceleration", "Mass", "Power"], "answer": 0}, {"type": "mc", "q": "Constant positive acceleration makes velocity-time graph:", "options": ["Horizontal", "Straight line with positive slope", "Circle", "Vertical line"], "answer": 1}, {"type": "mc", "q": "Negative velocity means:", "options": ["Object must be slowing", "Motion is in the negative chosen direction", "Acceleration is negative", "Position is negative"], "answer": 1}], "completed": true, "score": 14, "submittedAt": "Aug 30 at 7:54 PM", "feedback": "Good. Remember velocity sign describes direction, not whether speed is increasing.", "reviewLectureId": "phys-l1b", "timeLimit": 20, "sampleAnswers": ["1", "0", "1", "1"]}, {"id": "phys-vector-check", "title": "Quiz · Vectors & Components", "due": "Sep 6 at 11:59 PM", "points": 15, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A 10-N vector at 30° above +x has y-component:", "options": ["8.66 N", "5.0 N", "10 N", "3.0 N"], "answer": 1}, {"type": "mc", "q": "Vector components are useful because:", "options": ["Perpendicular directions can be analyzed independently", "They remove units", "They make all forces equal", "They eliminate geometry"], "answer": 0}, {"type": "mc", "q": "Magnitude from components 3 and 4 is:", "options": ["5", "7", "12", "1"], "answer": 0}, {"type": "mc", "q": "A negative x-component means:", "options": ["The vector has a component toward −x", "The vector has no direction", "Magnitude is negative", "y must be zero"], "answer": 0}], "completed": true, "score": 15, "submittedAt": "Sep 6 at 6:52 PM", "feedback": "Excellent.", "reviewLectureId": "phys-l2b", "timeLimit": 20, "sampleAnswers": ["1", "0", "0", "0"]}, {"id": "phys-friction-set", "title": "Problem Set · Friction & Inclined Planes", "due": "Sep 12 at 11:59 PM", "points": 30, "group": "Homework", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. A 10-kg block rests on a horizontal floor. Find its weight and normal force if no other vertical forces act."}, {"type": "textarea", "q": "2. The same block has μk=0.25 and slides horizontally. Find kinetic friction magnitude."}, {"type": "textarea", "q": "3. A block rests on a 30° incline. Resolve its weight into components parallel and perpendicular to the plane."}, {"type": "textarea", "q": "4. Explain the difference between static friction “up to a maximum” and kinetic friction."}, {"type": "textarea", "q": "5. Write a short solution strategy for an incline problem before doing algebra."}], "instructions": "Start with an FBD. Choose axes that make the geometry simpler—often parallel/perpendicular to the incline.", "completed": false, "rubric": [["FBDs", 8, "All external forces shown"], ["Components", 7, "Correct trig and signs"], ["Newton equations", 8, "Correct axis equations"], ["Concept explanation", 4, "Static vs kinetic friction"], ["Presentation", 3, "Units and logic"]], "context": "Friction problems become manageable when you stop treating friction as a memorized direction. Determine the tendency of relative motion, then assign friction opposing that tendency.", "steps": ["Isolate the object.", "Choose axes.", "Draw weight and contact forces.", "Resolve components.", "Decide whether friction is static or kinetic.", "Apply Newton’s second law per axis.", "Check signs and units."], "workedExample": "For a 10-kg block on level ground, W=mg≈98.1 N downward. With no other vertical acceleration, N≈98.1 N upward. If μk=.25, fk=μkN≈24.5 N.", "supportResources": ["openstaxFbd"], "reviewLectureId": "phys-l3b"}, {"id": "phys-fbd-quiz", "title": "Quiz · Newton’s Laws & Free-Body Diagrams", "due": "Sep 11 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A book at rest on a table has:", "options": ["Weight only", "Normal only", "Weight down and normal up", "No forces"], "answer": 2}, {"type": "mc", "q": "Action-reaction pairs act:", "options": ["On the same object", "On different interacting objects", "Only vertically", "Only during motion"], "answer": 1}, {"type": "mc", "q": "Net force 12 N on 4 kg gives acceleration:", "options": ["3 m/s²", "48 m/s²", "0.33 m/s²", "16 m/s²"], "answer": 0}, {"type": "mc", "q": "Friction direction is determined by:", "options": ["Always left", "Opposing actual or impending relative sliding", "Always opposite velocity of the universe", "Gravity"], "answer": 1}, {"type": "mc", "q": "If acceleration is zero, net force is:", "options": ["Zero", "Equal to weight always", "Infinite", "Unknown by definition"], "answer": 0}, {"type": "mc", "q": "A normal force is:", "options": ["Always equal to weight", "A contact force perpendicular to the surface", "Always horizontal", "A field force"], "answer": 1}], "completed": false, "context": "Conceptual checkpoint before the mechanics unit test.", "supportResources": ["openstaxFbd", "khanFbd"], "reviewLectureId": "phys-l3", "timeLimit": 25}, {"id": "phys-unit1-test", "title": "Mechanics Test 1 · Kinematics, Vectors & Forces", "due": "Sep 13 at 11:59 PM", "points": 40, "group": "Exams", "kind": "quiz", "questions": [{"type": "mc", "q": "Velocity is the time rate of change of:", "options": ["Acceleration", "Position", "Force", "Energy"], "answer": 1}, {"type": "mc", "q": "Area under acceleration-time graph gives change in:", "options": ["Position", "Velocity", "Mass", "Force"], "answer": 1}, {"type": "mc", "q": "Vector magnitude from 6 and 8 components is:", "options": ["10", "14", "48", "2"], "answer": 0}, {"type": "mc", "q": "A 20-N vector at 60° above +x has x-component:", "options": ["10 N", "17.3 N", "20 N", "5 N"], "answer": 0}, {"type": "mc", "q": "Newton’s second law is:", "options": ["F=ma", "E=mc²", "p=mv only", "V=IR"], "answer": 0}, {"type": "mc", "q": "A free-body diagram includes forces:", "options": ["Acting on the isolated object", "Exerted by the object on everything else", "Only internal forces", "Only gravity"], "answer": 0}, {"type": "mc", "q": "On a level surface with no vertical acceleration, normal force equals weight only when:", "options": ["No other vertical forces act", "The object moves fast", "Friction is zero", "Mass is zero"], "answer": 0}, {"type": "mc", "q": "Kinetic friction magnitude in the simple model is:", "options": ["μkN", "mg/μ", "N/μ", "Always zero"], "answer": 0}, {"type": "mc", "q": "If net force points +x, acceleration points:", "options": ["−x", "+x", "Always upward", "No direction"], "answer": 1}, {"type": "mc", "q": "The best first step in a Newton-law word problem is often:", "options": ["Plug numbers immediately", "Define system and draw FBD", "Guess the answer", "Convert to energy"], "answer": 1}], "completed": false, "context": "Cumulative assessment for Weeks 1–3. It is designed to show what concept needs review, not just produce a number.", "supportResources": ["openstaxFbd"], "reviewLectureId": "phys-l3b", "timeLimit": 50}], "ewrt1a": [{"id": "ewrt-annotation", "title": "Reading Lab · Annotation for Claims, Evidence & Moves", "due": "Aug 29 at 11:59 PM", "points": 20, "group": "Reading", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. In a short article of your choice, identify the main claim in one sentence."}, {"type": "textarea", "q": "2. Quote or paraphrase one piece of evidence and explain what claim it supports."}, {"type": "textarea", "q": "3. Identify one rhetorical move the writer makes (definition, example, concession, comparison, cause/effect, etc.)."}, {"type": "textarea", "q": "4. Write one question your annotation leaves you wanting to investigate."}], "instructions": "Annotation is not highlighting everything. Mark the parts that help you reconstruct what the writer is doing and why.", "completed": true, "score": 19, "submittedAt": "Aug 29 at 9:40 PM", "feedback": "Good distinction between evidence and the author’s interpretive move. Your follow-up question is specific enough to guide research.", "sampleAnswers": ["The author argues that campus transit reliability matters more than adding routes alone.", "The article compares missed-connection rates before and after schedule changes; this supports the reliability claim.", "Concession: the writer acknowledges that route expansion can help but argues operations still control user experience.", "How do riders with late-night shifts experience the same system?"], "rubric": [["Claim", 5, "Accurate and concise"], ["Evidence", 5, "Relevant and connected"], ["Rhetorical move", 5, "Correctly identified and explained"], ["Inquiry question", 5, "Specific and researchable"]], "context": "Good readers do not only ask “what does this say?” They ask “what is this paragraph doing in the argument?”", "reviewLectureId": "ewrt-l1b"}, {"id": "ewrt-argument-check", "title": "Quiz · Claim, Evidence, Warrant & Counterargument", "due": "Sep 5 at 11:59 PM", "points": 15, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A warrant is:", "options": ["The connection explaining why evidence supports a claim", "A bibliography", "Any quotation", "A title"], "answer": 0}, {"type": "mc", "q": "Strong evidence is strongest when it is:", "options": ["Relevant, credible and interpreted", "Long", "Dramatic", "Unexplained"], "answer": 0}, {"type": "mc", "q": "A counterargument improves an essay when it is:", "options": ["Misrepresented", "Addressed fairly and specifically", "Ignored", "Used only in the title"], "answer": 1}, {"type": "mc", "q": "A thesis should generally be:", "options": ["Arguable and specific", "A fact no one can dispute", "A question only", "A list of sources"], "answer": 0}, {"type": "mc", "q": "A paragraph should usually have:", "options": ["A clear function in the larger argument", "Exactly five sentences", "No transitions", "Only quotation"], "answer": 0}], "completed": true, "score": 14, "submittedAt": "Sep 5 at 8:32 PM", "feedback": "Strong. Revisit warrant language—your evidence may be good but the reader still needs the reasoning bridge.", "reviewLectureId": "ewrt-l2", "timeLimit": 20, "sampleAnswers": ["0", "0", "1", "0", "0"]}, {"id": "ewrt-paragraph-revision", "title": "Workshop · Revise One Body Paragraph Deeply", "due": "Sep 11 at 11:59 PM", "points": 25, "group": "Writing", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Paste the original version of one body paragraph."}, {"type": "textarea", "q": "2. In one sentence, state the job this paragraph should do in your essay."}, {"type": "textarea", "q": "3. Rewrite the topic sentence so it advances the thesis rather than merely naming a topic."}, {"type": "textarea", "q": "4. Revise the evidence integration. Include setup/context, evidence, and your analysis."}, {"type": "textarea", "q": "5. Paste the revised paragraph."}, {"type": "textarea", "q": "6. Explain the three most important changes you made and why."}], "instructions": "Do not try to “make it sound smarter.” Revise for logic: claim → evidence → warrant → connection to thesis.", "completed": false, "rubric": [["Paragraph purpose", 4, "Clear function in argument"], ["Claim/topic sentence", 5, "Specific and thesis-linked"], ["Evidence integration", 5, "Context and source use"], ["Analysis/warrant", 7, "Explains why evidence matters"], ["Reflection", 4, "Names meaningful revisions"]], "context": "Deep revision teaches more than proofreading ten pages. This assignment isolates one paragraph so you can see how argument structure changes at sentence level.", "steps": ["Name the paragraph’s job.", "Underline the claim.", "Bracket the evidence.", "Circle the warrant/analysis.", "Find any sentence that does not serve the paragraph’s job.", "Rewrite and compare before/after."], "workedExample": "Weak analysis: “This quote shows the problem is important.” Stronger: explain exactly what feature of the evidence changes the reader’s understanding and why it supports your thesis.", "supportResources": ["purdueWriting"], "reviewLectureId": "ewrt-l3b"}, {"id": "ewrt-peer-review", "title": "Peer Review · Argument Draft", "due": "Sep 12 at 11:59 PM", "points": 20, "group": "Participation", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Summarize the draft’s main claim in your own words."}, {"type": "textarea", "q": "2. Identify the strongest paragraph and explain why it works."}, {"type": "textarea", "q": "3. Identify one place where the writer needs more evidence or analysis."}, {"type": "textarea", "q": "4. Write one question that would help the writer clarify a counterargument or limitation."}, {"type": "textarea", "q": "5. Give one prioritized revision recommendation—what should the writer fix first?"}], "instructions": "Respond as a reader, not a copy editor. Focus on argument, organization, evidence, and clarity before grammar.", "completed": false, "rubric": [["Summary accuracy", 4, "Represents the argument fairly"], ["Specific feedback", 8, "Points to concrete locations/issues"], ["Revision priority", 4, "Actionable and important"], ["Tone", 4, "Constructive and reader-focused"]], "context": "Useful peer review helps another writer see how the draft actually lands on a reader. It should be specific enough to act on.", "reviewLectureId": "ewrt-l3b"}, {"id": "ewrt-w3-check", "title": "Week 3 Check · Drafting & Revision Decisions", "due": "Sep 13 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "The strongest revision pass usually begins with:", "options": ["Comma hunting", "Argument and organization", "Font changes", "Citation punctuation only"], "answer": 1}, {"type": "mc", "q": "A topic sentence should:", "options": ["Advance the paragraph’s role in the thesis", "Always begin with a quote", "Be a dictionary definition", "Repeat the assignment prompt"], "answer": 0}, {"type": "mc", "q": "Evidence without analysis often leaves the reader asking:", "options": ["Why does this prove the point?", "What font is this?", "How long is the essay?", "Where is the cover page?"], "answer": 0}, {"type": "mc", "q": "A fair counterargument should be:", "options": ["A weak caricature", "A plausible opposing view represented accurately", "Deleted", "Only one sentence long by rule"], "answer": 1}, {"type": "mc", "q": "Revision differs from proofreading because revision:", "options": ["Changes ideas/structure/logic while proofreading polishes surface errors", "Is only spellcheck", "Never changes paragraphs", "Happens before drafting"], "answer": 0}], "completed": false, "context": "Short conceptual assessment after the drafting and revision workshops.", "supportResources": ["purdueWriting"], "reviewLectureId": "ewrt-l3b", "timeLimit": 25}], "const20": [{"id": "const-drawing-check", "title": "Quiz · Drawing Set Navigation", "due": "Aug 29 at 11:59 PM", "points": 15, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A plan view is primarily:", "options": ["A top-down horizontal view", "A cut through a wall", "A 3D rendering", "A cost estimate"], "answer": 0}, {"type": "mc", "q": "A section is useful because it:", "options": ["Shows relationships through a cut assembly", "Only lists doors", "Shows schedule dates", "Replaces all details"], "answer": 0}, {"type": "mc", "q": "A detail callout is meant to:", "options": ["Point to enlarged information about a specific condition", "Hide dimensions", "Show payroll", "Measure concrete strength"], "answer": 0}, {"type": "mc", "q": "Before scaling a printed drawing, you should prefer:", "options": ["Written dimensions when available", "Eyeballing", "Screen pixels", "No dimensions"], "answer": 0}, {"type": "mc", "q": "A schedule commonly organizes:", "options": ["Repeated items such as doors/finishes", "Only structural loads", "Weather", "Payroll"], "answer": 0}], "completed": true, "score": 15, "submittedAt": "Aug 29 at 6:43 PM", "feedback": "Perfect.", "reviewLectureId": "const-l1", "timeLimit": 20, "sampleAnswers": ["0", "0", "0", "0", "0"]}, {"id": "const-safety-check", "title": "Safety Check · Construction Hazard Recognition", "due": "Aug 30 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A useful pre-task safety question is:", "options": ["What can hurt someone during this step?", "Which logo looks best?", "How fast can we skip setup?", "Who can ignore the plan?"], "answer": 0}, {"type": "mc", "q": "Fall protection planning is most effective when:", "options": ["Addressed before exposure begins", "Discussed only after a fall", "Left entirely to memory", "Ignored for short tasks"], "answer": 0}, {"type": "mc", "q": "Housekeeping affects safety because:", "options": ["Trips, access and material handling can create hazards", "It only changes appearance", "It replaces PPE", "It removes need for planning"], "answer": 0}, {"type": "mc", "q": "An RFI should be used when:", "options": ["Information conflicts or is insufficient for a decision", "You want to guess silently", "You dislike the font", "A drawing is colorful"], "answer": 0}, {"type": "mc", "q": "Good safety communication is:", "options": ["Specific to the task and hazard", "Generic only", "Never documented", "Only for managers"], "answer": 0}], "completed": true, "score": 19, "submittedAt": "Aug 30 at 8:11 PM", "feedback": "Strong hazard-recognition thinking.", "supportResources": ["oshaFalls", "oshaVideos"], "reviewLectureId": "const-l1b", "timeLimit": 25, "sampleAnswers": ["0", "0", "0", "0", "0"]}, {"id": "const-concrete-check", "title": "Quiz · Concrete, Reinforcement & Foundations", "due": "Sep 5 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "Concrete is generally strong in:", "options": ["Compression", "Tension only", "Electric conduction", "Nothing"], "answer": 0}, {"type": "mc", "q": "Steel reinforcement is commonly used to help concrete resist:", "options": ["Tension and cracking demands", "Color fading only", "Sound", "Thermal expansion only"], "answer": 0}, {"type": "mc", "q": "A 4-in slab thickness should be converted to feet as:", "options": ["4 ft", "0.333 ft", "0.04 ft", "48 ft"], "answer": 1}, {"type": "mc", "q": "Concrete volume is commonly ordered in:", "options": ["Cubic yards", "Square feet only", "Linear feet only", "Gallons by default"], "answer": 0}, {"type": "mc", "q": "Moisture control at foundations matters because:", "options": ["Water can migrate into assemblies and damage materials/indoor conditions", "Concrete dissolves instantly", "It changes gravity", "It eliminates structure"], "answer": 0}], "completed": true, "score": 20, "submittedAt": "Sep 5 at 7:22 PM", "feedback": "Excellent.", "supportResources": ["practicalConcrete", "doeFoundation"], "reviewLectureId": "const-l2", "timeLimit": 25, "sampleAnswers": ["0", "0", "1", "0", "0"]}, {"id": "const-estimate-detail", "title": "Estimating Lab · Quantity → Waste → Cost", "due": "Sep 6 at 11:59 PM", "points": 25, "group": "Estimating", "kind": "worksheet", "questions": [{"type": "text", "q": "1. A room needs 180 SF of floor finish. Add 8% waste. What purchase quantity do you carry?"}, {"type": "text", "q": "2. Material costs $3.85/SF. Estimate material cost using the purchase quantity."}, {"type": "textarea", "q": "3. Explain why waste should be stated as an assumption rather than hidden inside the quantity."}, {"type": "textarea", "q": "4. List three things that could make a field quantity differ from an early drawing takeoff."}, {"type": "textarea", "q": "5. Write one sentence you would place in estimate notes to document scope."}], "instructions": "Carry quantities transparently from measured scope to adjusted purchase quantity to cost.", "completed": true, "score": 24, "submittedAt": "Sep 6 at 9:47 PM", "feedback": "Very good estimate notes. You separated measured quantity from waste, which makes later reconciliation much easier.", "sampleAnswers": ["194.4 SF (or round based on product packaging).", "$748.44 before tax/other markups if using 194.4 SF.", "Separating waste shows the estimator’s assumption and allows someone to update it without remeasuring base scope.", "Design changes, field dimensions, openings, product modules/packaging, installation method, damage, measurement error.", "Includes floor finish in Room 101 based on 180 SF net plan area plus 8% waste; excludes substrate repair."], "rubric": [["Base quantity", 5, "Correct"], ["Waste adjustment", 5, "Transparent"], ["Cost extension", 5, "Correct units/arithmetic"], ["Assumptions", 5, "Clear"], ["Scope note", 5, "Specific inclusions/exclusions"]], "context": "Estimating is a chain of assumptions. A useful estimate lets another person trace where each number came from.", "supportResources": ["autodeskEstimate"], "reviewLectureId": "const-l2b"}, {"id": "const-framing-check2", "title": "Quiz · Framing, Load Transfer & Openings", "due": "Sep 11 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A header above an opening primarily helps:", "options": ["Transfer load around the opening", "Ventilate the room", "Replace foundation", "Create insulation"], "answer": 0}, {"type": "mc", "q": "A stud wall transfers vertical load generally toward:", "options": ["Bottom plate/floor/foundation path", "Roof sky", "Window glass only", "Electrical panel"], "answer": 0}, {"type": "mc", "q": "A trimmer/jack stud commonly supports:", "options": ["Header end reaction", "Roof membrane only", "Door hardware only", "Paint"], "answer": 0}, {"type": "mc", "q": "A continuous load path matters because:", "options": ["Strong members still need reliable connections", "Loads disappear at joints", "Only foundations matter", "It is aesthetic"], "answer": 0}, {"type": "mc", "q": "When framing conflicts with duct routing, best response is:", "options": ["Coordinate and clarify before cutting structural members", "Cut anything needed", "Ignore drawings", "Move columns without review"], "answer": 0}], "completed": false, "supportResources": ["doeFraming", "jeffTruss"], "reviewLectureId": "const-l3", "timeLimit": 25}, {"id": "const-rfi-lab", "title": "Coordination Lab · Write an RFI", "due": "Sep 12 at 11:59 PM", "points": 25, "group": "Coordination", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Scenario: Architectural plan shows a 3'-0\" door while the door schedule lists 3'-6\". Write a concise RFI subject."}, {"type": "textarea", "q": "2. Describe the conflict using sheet/detail references you would cite in a real set."}, {"type": "textarea", "q": "3. State the specific question the design team must answer."}, {"type": "textarea", "q": "4. Explain the schedule/cost risk of proceeding without clarification."}, {"type": "textarea", "q": "5. Suggest a reasonable “requested by” date and explain how you chose it."}], "instructions": "An RFI is not a complaint and not an invitation to redesign the project casually. It isolates a conflict and asks a question that can be answered.", "completed": false, "rubric": [["Subject", 3, "Specific"], ["References", 5, "Identifies conflicting information"], ["Question", 7, "Clear and answerable"], ["Impact", 5, "Explains risk"], ["Need date", 5, "Connected to sequence"]], "context": "Construction work depends on coordinated information. Learning to ask a precise technical question is a core field/project-management skill.", "steps": ["Name the issue clearly.", "Cite the conflicting documents.", "Describe observed conflict without blame.", "Ask one answerable question.", "State impact if unresolved.", "Set a response need-date based on the work sequence."], "workedExample": "Subject: Door 102 width conflict — A2.1 vs Door Schedule. Question: Please confirm required rough opening/door width for Door 102 before framing layout on Sep 15.", "reviewLectureId": "const-l3c"}, {"id": "const-w3-test", "title": "Week 3 Test · Framing, Envelope & Coordination", "due": "Sep 13 at 11:59 PM", "points": 40, "group": "Exams", "kind": "quiz", "questions": [{"type": "mc", "q": "A header is used to:", "options": ["Carry load over an opening", "Stop all moisture", "Measure concrete", "Replace a footing"], "answer": 0}, {"type": "mc", "q": "Building enclosure layers should manage:", "options": ["Water, air, heat and vapor as applicable", "Only paint color", "Payroll", "Traffic signals"], "answer": 0}, {"type": "mc", "q": "Flashing is primarily intended to:", "options": ["Direct water to the exterior/drainage path", "Increase live load", "Replace insulation", "Carry gravity load"], "answer": 0}, {"type": "mc", "q": "An RFI is appropriate when:", "options": ["Contract information conflicts or needs clarification", "You want to hide an assumption", "You do not want to read the drawings", "Everything is clear"], "answer": 0}, {"type": "mc", "q": "Quantity takeoff should document:", "options": ["Units, deductions and assumptions", "Only final cost", "No source", "Only waste"], "answer": 0}, {"type": "mc", "q": "Wall finish is commonly measured in:", "options": ["Square feet", "Cubic yards", "Miles", "Pounds only"], "answer": 0}, {"type": "mc", "q": "Baseboard is commonly measured in:", "options": ["Linear feet", "Square feet", "Cubic feet", "Tons"], "answer": 0}, {"type": "mc", "q": "An opening deduction should be:", "options": ["Applied according to documented estimating rules/assumptions", "Always ignored", "Always doubled", "Hidden"], "answer": 0}, {"type": "mc", "q": "A reliable load path requires:", "options": ["Members and connections that transfer force continuously", "Only strong paint", "No fasteners", "No foundation"], "answer": 0}, {"type": "mc", "q": "Best response to a structural framing/MEP conflict:", "options": ["Coordinate before unauthorized modification", "Cut the member", "Ignore it", "Cover it up"], "answer": 0}], "completed": false, "context": "Cumulative construction assessment for drawing reading, quantities, materials, framing and coordination.", "supportResources": ["doeBuilding", "oshaVideos"], "reviewLectureId": "const-l3c", "timeLimit": 50}]};
const V7_MUSIC_COURSE={"id": "musi3a", "code": "MUSI 3A", "title": "Comprehensive Musicianship (First Quarter)", "instructor": "Prof. Sofia Alvarez", "room": "Hybrid Demo · Music Room A91 + Online Ear Lab", "schedule": "Monday · 10:30 AM–12:20 PM · Hybrid + online practice", "units": 4, "color": "#7a4f86", "grade": 95, "modality": "Hybrid + Online Ear Training", "week": "Week 3", "description": "A fictional learning simulation using the public De Anza MUSI 3A course identity as inspiration. The lessons, professor, classmates, grades, meetings, assignments, and recordings here are original fictional demo content. Study rhythm, notation, scales, intervals, triads, Roman numerals, ear training, keyboard/guitar application, and practical musicianship.", "gradeGroups": [["Theory Assignments", 30, 96], ["Ear Training", 20, 92], ["Quizzes", 20, 98], ["Musicianship Labs", 20, 95], ["Participation", 10, 100]], "lectures": {}, "assignments": [{"id": "musi-orient", "title": "Orientation · Music Learning Baseline", "due": "Aug 24 at 11:59 PM", "points": 10, "group": "Participation", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. What instrument(s), if any, do you currently play?"}, {"type": "textarea", "q": "2. Which feels hardest right now: reading notation, rhythm, ear training, scales, chords, or harmony? Why?"}, {"type": "textarea", "q": "3. Write one practical goal for the end of the quarter."}, {"type": "text", "q": "4. How many days per week can you realistically practice 10–20 minutes?"}], "instructions": "This baseline is for reflection, not musical perfection. Honest answers help you compare your growth later.", "completed": true, "score": 10, "submittedAt": "Aug 24 at 8:02 PM", "feedback": "Clear goals. Your plan to connect theory to guitar voicings will be useful.", "sampleAnswers": ["Guitar and some bass.", "Reading notation and hearing intervals by ear feel least automatic.", "Understand why chords work together and be able to hear/identify common intervals and triads.", "5"], "rubric": [["Reflection", 4, "Specific and honest"], ["Goal", 3, "Concrete"], ["Practice plan", 3, "Realistic"]], "context": "Musicianship grows from repeated small connections: see it, name it, hear it, play it.", "reviewLectureId": "musi-l1"}, {"id": "musi-rhythm-sheet", "title": "Musicianship Lab 1 · Pulse, Subdivision & Rhythm", "due": "Aug 28 at 11:59 PM", "points": 20, "group": "Musicianship Labs", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. In 4/4, write a one-measure rhythm using quarter notes and eighth notes that totals four beats. Explain your count syllables."}, {"type": "textarea", "q": "2. Explain the difference between beat and subdivision."}, {"type": "textarea", "q": "3. At 72 BPM, clap quarter notes for 30 seconds, then eighth notes for 30 seconds. What changed physically while the pulse stayed the same?"}, {"type": "textarea", "q": "4. Describe where you feel beat 1 in a four-beat measure and why it helps orientation."}, {"type": "textarea", "q": "5. Practice with the metronome tool and record one observation about rushing or dragging."}], "instructions": "Count out loud. Rhythm becomes much easier when the counting system stays consistent.", "completed": true, "score": 19, "submittedAt": "Aug 28 at 9:16 PM", "feedback": "Good physical description of subdivision. Keep the foot/pulse steady while the hands change density.", "sampleAnswers": ["Example: 1 & 2 3 & 4, using two eighth-note pairs and two quarters.", "Beat is the underlying pulse; subdivision divides each beat into smaller equal parts.", "My hands moved twice as often on eighth notes while the click/pulse stayed unchanged.", "Beat 1 marks the start of the measure and helps track phrase location.", "I tend to rush the second half of the measure when I stop counting aloud."], "rubric": [["Counting", 5, "Correct duration totals"], ["Concepts", 5, "Beat vs subdivision"], ["Practice reflection", 5, "Specific observation"], ["Musical clarity", 5, "Connects pulse to meter"]], "context": "Rhythm is not “math instead of music.” It is how musical time is organized so performers can coordinate and shape phrases.", "reviewLectureId": "musi-l1b"}, {"id": "musi-note-quiz", "title": "Quiz 1 · Staff, Note Values & Meter", "due": "Aug 30 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "In treble clef, the lines from bottom to top are:", "options": ["E G B D F", "F A C E G", "G B D F A", "C D E F G"], "answer": 0}, {"type": "mc", "q": "A half note in 4/4 usually lasts:", "options": ["1 beat", "2 beats", "3 beats", "4 beats"], "answer": 1}, {"type": "mc", "q": "Two eighth notes together equal:", "options": ["One quarter-note beat", "Two whole notes", "One half-note beat only", "Four beats"], "answer": 0}, {"type": "mc", "q": "The top number of 4/4 tells you:", "options": ["Four beat units per measure", "Quarter note is always loud", "Four sharps", "Tempo"], "answer": 0}, {"type": "mc", "q": "A rest represents:", "options": ["Measured silence", "A wrong note", "A key signature", "A chord inversion"], "answer": 0}, {"type": "mc", "q": "Subdivision means:", "options": ["Dividing the beat into smaller equal parts", "Changing key", "Playing louder", "Ending a song"], "answer": 0}], "completed": true, "score": 19, "submittedAt": "Aug 30 at 7:07 PM", "feedback": "Great start. Review one treble-clef note-name item.", "context": "This checks basic notation literacy so later harmony work does not get slowed down by symbol recognition.", "reviewLectureId": "musi-l1b", "timeLimit": 20, "sampleAnswers": ["0", "1", "0", "0", "0", "0"]}, {"id": "musi-scale-sheet", "title": "Theory Assignment 2 · Build Major Scales", "due": "Sep 3 at 11:59 PM", "points": 25, "group": "Theory Assignments", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Write the whole/half-step pattern for a major scale."}, {"type": "textarea", "q": "2. Spell the G major scale and identify its key-signature accidental."}, {"type": "textarea", "q": "3. Spell the D major scale and identify its key-signature accidentals."}, {"type": "textarea", "q": "4. Why should a correctly spelled seven-note scale use each letter name once?"}, {"type": "textarea", "q": "5. On guitar or keyboard, play C, G, and D major scales slowly. Describe one fingering/visual pattern you notice."}], "instructions": "Spell first, then check semitone distances. Do not solve every scale by guessing sharps on a chromatic list.", "completed": true, "score": 24, "submittedAt": "Sep 3 at 10:03 PM", "feedback": "Strong spelling. Your explanation of one letter name per scale degree was especially clear.", "sampleAnswers": ["W-W-H-W-W-W-H", "G A B C D E F# G; one sharp F#", "D E F# G A B C# D; F# and C#", "Each scale degree has a distinct letter identity, which makes intervals and chord spelling readable.", "On guitar the physical box can shift, but note names/key spelling tell me what each position means harmonically."], "rubric": [["Pattern", 5, "Correct whole/half sequence"], ["G major", 5, "Correct spelling"], ["D major", 5, "Correct spelling"], ["Notation logic", 5, "Explains letter use"], ["Applied practice", 5, "Connects theory to instrument"]], "context": "Scale spelling is the grammar behind intervals and chords. If the letters are wrong, later chord spelling becomes confusing even when the pitches sound close.", "supportResources": ["musicKeySigs"], "reviewLectureId": "musi-l2"}, {"id": "musi-key-quiz", "title": "Quiz 2 · Major Scales & Key Signatures", "due": "Sep 5 at 11:59 PM", "points": 20, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "Major-scale step pattern is:", "options": ["W-W-H-W-W-W-H", "W-H-W-H-W-H-W", "H-H-W-W-H-W-W", "W-W-W-W-W-W-W"], "answer": 0}, {"type": "mc", "q": "G major contains:", "options": ["F#", "Bb", "C# and F#", "No accidentals"], "answer": 0}, {"type": "mc", "q": "D major contains:", "options": ["F# and C#", "Bb and Eb", "F# only", "C# only"], "answer": 0}, {"type": "mc", "q": "Why use each letter name once in a diatonic scale?", "options": ["To represent distinct scale degrees clearly", "Because sharps are forbidden", "To make every scale C major", "Because rhythm requires it"], "answer": 0}, {"type": "mc", "q": "The leading tone in C major is:", "options": ["B", "C", "A", "F"], "answer": 0}], "completed": true, "score": 20, "submittedAt": "Sep 5 at 8:28 PM", "feedback": "Perfect.", "supportResources": ["musicKeySigs"], "reviewLectureId": "musi-l2", "timeLimit": 20, "sampleAnswers": ["0", "0", "0", "0", "0"]}, {"id": "musi-interval-lab", "title": "Ear + Theory Lab · Intervals", "due": "Sep 6 at 11:59 PM", "points": 25, "group": "Ear Training", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Explain the two-part process for naming a written interval: number + quality."}, {"type": "textarea", "q": "2. Name C→E, C→Eb, C→F, C→G, and C→B."}, {"type": "textarea", "q": "3. Use the interval trainer for at least 10 trials. Record your score and which interval confused you most."}, {"type": "textarea", "q": "4. Pick one song or riff you know and identify one interval you can hear or play in it."}, {"type": "textarea", "q": "5. Explain why counting semitones alone can be insufficient for correct written interval spelling."}], "instructions": "Do written identification and listening back-to-back. The goal is to connect symbol, sound, and instrument.", "completed": true, "score": 23, "submittedAt": "Sep 6 at 9:14 PM", "feedback": "Nice connection between semitone size and letter spelling. Keep drilling minor vs major 3rd by singing the upper note before checking.", "sampleAnswers": ["Count letter names for the generic interval, then compare semitone size to determine major/minor/perfect/augmented/diminished quality.", "M3, m3, P4, P5, M7.", "8/10; minor vs major 3rd was hardest.", "The opening of a familiar riff uses repeated perfect-fourth motion between two notes.", "Enharmonic pitches can have the same semitone distance but different written functions/letter spans."], "rubric": [["Written theory", 8, "Correct interval process/names"], ["Trainer practice", 5, "Documented repeated listening"], ["Applied example", 5, "Connects to real music"], ["Spelling explanation", 7, "Distinguishes sound distance and notation function"]], "context": "Intervals are the distance vocabulary of melody and harmony. You want to recognize them three ways: on the page, in your ear, and under your fingers.", "supportResources": ["musicIntervals", "guitarIntervals"], "reviewLectureId": "musi-l2b"}, {"id": "musi-triad-sheet", "title": "Theory Assignment 3 · Build & Analyze Triads", "due": "Sep 11 at 11:59 PM", "points": 30, "group": "Theory Assignments", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Build C major, C minor, and C diminished triads. Spell every note and identify the intervals above the root."}, {"type": "textarea", "q": "2. Build the diatonic triads on scale degrees I–vii° in C major and label each quality."}, {"type": "textarea", "q": "3. In G major, spell I, IV, V, and vi."}, {"type": "textarea", "q": "4. Explain why G–B–D is a G major triad even if the notes appear in another order."}, {"type": "textarea", "q": "5. On guitar or keyboard, play I–V–vi–IV in C major. Name every chord and describe which voices/notes can move by the smallest distance between chords."}, {"type": "textarea", "q": "6. Reflection: what is the difference between chord spelling and chord voicing?"}], "instructions": "Write chord spellings before reaching for a shape. Then play them. This is how theory becomes transferable beyond memorized guitar boxes.", "completed": false, "rubric": [["Chord spelling", 10, "Correct roots/thirds/fifths"], ["Diatonic qualities", 6, "I ii iii IV V vi vii°"], ["Key application", 5, "Correct G-major chords"], ["Instrument application", 5, "Connects voicing/voice-leading"], ["Explanation", 4, "Spelling vs voicing"]], "context": "Triads are where scales turn into harmony. If you can spell a key and identify thirds, you can derive the diatonic chord family rather than memorizing a chart.", "steps": ["Write the key/scale.", "Stack every other scale degree to form thirds.", "Spell root–third–fifth with correct letters.", "Measure interval qualities.", "Label major/minor/diminished.", "Play the result in more than one voicing if possible."], "workedExample": "C major triad: C–E–G. C→E is a major 3rd; C→G is a perfect 5th. C minor: C–Eb–G. C diminished: C–Eb–Gb.", "supportResources": ["musicChords", "beatoBasics"], "reviewLectureId": "musi-l3"}, {"id": "musi-harmony-quiz", "title": "Quiz 3 · Triads, Roman Numerals & Function", "due": "Sep 12 at 11:59 PM", "points": 25, "group": "Quizzes", "kind": "quiz", "questions": [{"type": "mc", "q": "A major triad contains:", "options": ["Root, major 3rd, perfect 5th", "Root, minor 3rd, diminished 5th", "Root and 7th only", "Three whole steps"], "answer": 0}, {"type": "mc", "q": "In C major, the ii chord is:", "options": ["D minor", "D major", "E minor", "F major"], "answer": 0}, {"type": "mc", "q": "In C major, V is:", "options": ["G major", "F major", "A minor", "B diminished"], "answer": 0}, {"type": "mc", "q": "Lowercase Roman numerals usually indicate:", "options": ["Minor/diminished quality as appropriate", "Tempo", "Loudness", "A sharp key"], "answer": 0}, {"type": "mc", "q": "The vii° triad in C major is:", "options": ["B-D-F", "B-D#-F#", "C-E-G", "A-C-E"], "answer": 0}, {"type": "mc", "q": "I–V–vi–IV in C major is:", "options": ["C-G-Am-F", "C-F-G-Am", "Am-F-C-G only", "G-D-Em-C"], "answer": 0}, {"type": "mc", "q": "An inversion changes primarily:", "options": ["Which chord member is in the bass", "The chord root identity necessarily", "The key signature", "The tempo"], "answer": 0}, {"type": "mc", "q": "Voice leading generally seeks:", "options": ["Purposeful movement between individual voices, often using small motions/common tones", "Random jumps only", "No shared notes", "Only root-position chords"], "answer": 0}], "completed": false, "context": "Theory checkpoint before the larger musicianship test.", "supportResources": ["musicChords"], "reviewLectureId": "musi-l3", "timeLimit": 30}, {"id": "musi-ear-journal", "title": "Ear Training Journal · Hear Before You Name", "due": "Sep 13 at 8:00 PM", "points": 20, "group": "Ear Training", "kind": "worksheet", "questions": [{"type": "textarea", "q": "1. Interval trainer: complete 15 trials. Record score and the two most-confused interval pairs."}, {"type": "textarea", "q": "2. Sing root→major 3rd→perfect 5th on a comfortable syllable. Describe which note is hardest to center."}, {"type": "textarea", "q": "3. Listen to a simple major-key song you know. Can you hear a point that feels like “home” (tonic)? Describe the moment."}, {"type": "textarea", "q": "4. Play I and V back and forth in one key. Describe the tension/release difference using your own words."}, {"type": "textarea", "q": "5. Write one 10-minute ear-training routine you could repeat this week."}], "instructions": "There is no prize for pretending you can hear something you cannot yet hear. Ear training improves when you notice exactly where recognition breaks down.", "completed": false, "rubric": [["Practice evidence", 5, "Repeated trials documented"], ["Listening description", 5, "Specific rather than vague"], ["Function hearing", 5, "Tonic/dominant reflection"], ["Practice plan", 5, "Repeatable and realistic"]], "context": "Ear training is pattern memory. Short, frequent sessions beat one exhausting cram session.", "steps": ["Establish a reference pitch/key.", "Sing before playing when possible.", "Guess before checking.", "Name the mistake specifically.", "Repeat the confusing pair immediately."], "supportResources": ["musicTheoryExercises", "beatoBasics"], "reviewLectureId": "musi-l3b"}, {"id": "musi-unit1-test", "title": "Musicianship Test 1 · Rhythm, Scales, Intervals & Triads", "due": "Sep 13 at 11:59 PM", "points": 40, "group": "Exams", "kind": "quiz", "questions": [{"type": "mc", "q": "Two eighth notes in simple 4/4 usually equal:", "options": ["One quarter-note beat", "Two measures", "A half note each", "Three beats"], "answer": 0}, {"type": "mc", "q": "Major scale pattern is:", "options": ["W-W-H-W-W-W-H", "W-H-W-W-H-W-W", "H-W-H-W-H-W-H", "All whole steps"], "answer": 0}, {"type": "mc", "q": "D major key signature contains:", "options": ["F# and C#", "Bb and Eb", "F# only", "No sharps"], "answer": 0}, {"type": "mc", "q": "C to Eb is:", "options": ["m3", "M3", "P4", "m2"], "answer": 0}, {"type": "mc", "q": "C to G is:", "options": ["P5", "P4", "M6", "m6"], "answer": 0}, {"type": "mc", "q": "A major triad is built:", "options": ["M3 + m3 stacked", "m3 + m3", "P4 + P4", "M2 + M2"], "answer": 0}, {"type": "mc", "q": "In C major, vi is:", "options": ["A minor", "A major", "F major", "B diminished"], "answer": 0}, {"type": "mc", "q": "In C major, vii° is:", "options": ["B diminished", "B minor", "G major", "D minor"], "answer": 0}, {"type": "mc", "q": "An inversion changes:", "options": ["Bass note/chord member order", "The song’s meter", "Every pitch class in the chord", "The key automatically"], "answer": 0}, {"type": "mc", "q": "Roman numeral V most often has what broad functional feeling in basic tonal harmony?", "options": ["Dominant/tension toward tonic", "Tonic rest only", "No relationship", "Rhythm"], "answer": 0}], "completed": false, "context": "Cumulative Weeks 1–3 test. After submission, use Study Center to reopen any lecture connected to missed concepts and practice the interactive tools again.", "supportResources": ["musicTheoryLessons", "musicTheoryExercises"], "reviewLectureId": "musi-l3b", "timeLimit": 50}], "discussions": [{"id": "musi-disc1", "title": "Week 1 · Where Do You Feel the Beat?", "due": "Aug 27 at 11:59 PM", "points": 10, "status": "graded", "score": 10, "prompt": "Choose one song you know well. Describe where you feel the main beat, whether you naturally subdivide it, and one rhythmic detail that makes the groove recognizable. No need for formal analysis yet—listen carefully and describe.", "posts": [{"name": "Nina Patel", "time": "Aug 26 · 6:12 PM", "text": "I used “Billie Jean.” I feel a really steady four-count under everything. The hi-hat makes the subdivisions feel smaller even though I am still tapping the same main beat.", "replies": [{"name": "Marcus Bell", "time": "Aug 26 · 6:29 PM", "text": "Same. I noticed I can tap quarter notes with my foot but my head wants to move with the eighth-note layer."}, {"name": "Prof. Sofia Alvarez", "time": "Aug 26 · 7:03 PM", "text": "That separation is exactly what we want: stable pulse underneath a denser subdivision layer."}]}, {"name": "Ethan Cole", "time": "Aug 27 · 4:21 PM", "text": "I picked a Metallica track. I can keep the big pulse, but the guitar rhythm makes me want to count every attack instead of the beat. Counting out loud made it less confusing.", "replies": [{"name": "Leah Tran", "time": "Aug 27 · 5:02 PM", "text": "That happens to me with syncopation too. The beat is still there even when the accents are between clicks."}]}]}, {"id": "musi-disc2", "title": "Week 2 · Interval Memory Without “Magic Songs”", "due": "Sep 4 at 11:59 PM", "points": 10, "status": "graded", "score": 10, "prompt": "Pick two intervals. Describe how they feel different to you in sound, singing, or on your instrument. Mnemonic songs are allowed, but go one step further: describe the tension, spacing, or physical shape you notice.", "posts": [{"name": "Avery Kim", "time": "Sep 3 · 7:14 PM", "text": "A perfect 5th feels open and stable to me, while a tritone feels like it wants to move somewhere. On keyboard the P5 shape is also visually easy to recognize.", "replies": [{"name": "Diego Flores", "time": "Sep 3 · 8:02 PM", "text": "The “open” word helped. I hear the fifth as less colored than a major third."}, {"name": "Prof. Sofia Alvarez", "time": "Sep 3 · 8:37 PM", "text": "Good. Descriptive language is useful when it is tied to repeated listening. Over time the label and the sound fuse."}]}, {"name": "Sofia Reyes", "time": "Sep 4 · 5:46 PM", "text": "Minor 3rd vs major 3rd is still hard. On guitar I can see the one-fret difference easily, but by ear I sometimes guess based on “sad/happy,” which is not reliable.", "replies": [{"name": "Nina Patel", "time": "Sep 4 · 6:10 PM", "text": "Same. Singing both from the same root back-to-back helped me more than song mnemonics."}]}]}, {"id": "musi-disc3", "title": "Week 3 · Why Does V Want to Go Home?", "due": "Sep 11 at 11:59 PM", "points": 10, "status": "open", "score": null, "prompt": "Play I–V–I in C, G, or another comfortable major key. Describe what changes when you move from I to V and back to I. Mention at least one note relationship, voice-leading motion, or scale degree that helps explain the feeling.", "posts": [{"name": "Jordan Smith", "time": "Sep 8 · 2:17 PM", "text": "In C, G major has B, which feels like it wants to move up to C. When I go G→C and keep G as a common tone, the other notes can move by small steps and it sounds settled.", "replies": [{"name": "Prof. Sofia Alvarez", "time": "Sep 8 · 2:48 PM", "text": "Excellent observation: scale degree 7 (B) resolving to 1 (C) is one of the strongest tonal cues. Also listen to F in a G7 resolving down to E when we add sevenths later."}, {"name": "Chris Park", "time": "Sep 8 · 3:10 PM", "text": "The common G helped me hear that the chords are connected instead of just two unrelated shapes."}]}, {"name": "Mia Johnson", "time": "Sep 8 · 4:22 PM", "text": "On guitar I played G major to D major to G. D felt more “unfinished.” I noticed F# in D wants to go up to G when I return.", "replies": [{"name": "Ethan Cole", "time": "Sep 8 · 4:49 PM", "text": "That is the same leading-tone idea but in G major. Seeing it in two keys made the Roman numerals make more sense."}]}]}], "zoomMeetings": [{"id": "musi-z1", "date": "Mon Aug 24", "time": "10:30 AM–12:20 PM", "title": "Week 1 · Pulse, Notation & Course Musicianship Lab", "status": "recording", "recording": "Class notes available", "agenda": ["How the course works", "Pulse vs subdivision", "Treble/bass staff orientation", "Clap-and-count lab", "Practice plan"], "notes": ["10:30–10:45 Setup and baseline", "10:45–11:20 Pulse/subdivision", "11:20–11:50 notation workshop", "11:50–12:20 applied rhythm practice"]}, {"id": "musi-z2", "date": "Mon Aug 31", "time": "10:30 AM–12:20 PM", "title": "Week 2 · Major Scales, Keys & Intervals", "status": "recording", "recording": "Class notes available", "agenda": ["Major-scale pattern", "Key signatures", "Interval number + quality", "Singing intervals", "Guitar/keyboard mapping"], "notes": ["10:30–10:50 review", "10:50–11:20 scale spelling", "11:20–11:50 intervals", "11:50–12:20 ear lab"]}, {"id": "musi-z3", "date": "Mon Sep 7", "time": "10:30 AM–12:20 PM", "title": "Week 3 · Triads, Roman Numerals & Hearing Function", "status": "recording", "recording": "Supplemental recorded excerpt included", "recordingId": "musi-rec3", "agenda": ["Build triads from scales", "Diatonic chord family", "Roman numerals", "I–V–vi–IV lab", "Ear training: tonic vs dominant"], "notes": ["Recording excerpt focuses on interval stacking into triads and hearing tonic/dominant pull."]}, {"id": "musi-z4", "date": "Mon Sep 14", "time": "10:30 AM–12:20 PM", "title": "Week 4 · Inversions, Cadences & Voice Leading", "status": "upcoming", "recording": "", "agenda": ["Triad inversions", "Cadences", "Common tones", "Smooth voice leading", "Applied progression lab"], "notes": []}], "modules": []};
const V7_EXTRA_DISCUSSIONS={"math1a": [{"id": "math-disc3", "title": "Week 3 · What Does a Derivative Mean Here?", "due": "Sep 11 at 11:59 PM", "points": 8, "status": "open", "score": null, "prompt": "Choose a quantity that changes—position, temperature, cost, volume, followers, fuel, etc. Define what its derivative with respect to another variable would mean and give the units.", "posts": [{"name": "Alex Morgan", "time": "Sep 8 · 12:44 PM", "text": "If C(q) is total cost in dollars to produce q items, C′(q) is the approximate additional cost per extra item near that production level, so units are dollars/item.", "replies": [{"name": "Taylor Nguyen", "time": "Sep 8 · 1:13 PM", "text": "That helped me see why derivative units are a division of the original units."}]}, {"name": "Leah Tran", "time": "Sep 8 · 3:27 PM", "text": "For water volume V(t) in gallons, V′(t) is net filling/draining rate in gallons per minute. Positive means volume is increasing.", "replies": [{"name": "Dr. Luis Ramirez", "time": "Sep 8 · 4:02 PM", "text": "Exactly. Interpretation plus units is as important as the symbolic derivative."}]}]}], "phys4a": [{"id": "phys-disc3", "title": "Week 3 · Isolate the System", "due": "Sep 12 at 11:59 PM", "points": 8, "status": "open", "score": null, "prompt": "Choose a simple force situation and state exactly what object/system you isolate. List the external forces on it, then name one force that would be wrong to include because it acts on a different object.", "posts": [{"name": "Casey Martinez", "time": "Sep 8 · 1:31 PM", "text": "System: a grocery cart being pushed. External forces: weight, normal, push from person, rolling resistance/friction. I would not put the force the cart pushes back on the person on the cart FBD because that force acts on the person.", "replies": [{"name": "Dr. Aisha Patel", "time": "Sep 8 · 2:06 PM", "text": "Good use of Newton’s third law: identify the pair, then place each force on the object it actually acts on."}]}, {"name": "Sam Rivera", "time": "Sep 8 · 5:18 PM", "text": "System: a hanging lamp. Weight downward and tension upward. The downward force the lamp exerts on the cable belongs on the cable’s FBD, not the lamp’s.", "replies": []}]}], "ewrt1a": [{"id": "ewrt-disc3", "title": "Week 3 · Revision Clinic: What Is the Paragraph Doing?", "due": "Sep 11 at 11:59 PM", "points": 10, "status": "open", "score": null, "prompt": "Post one body-paragraph topic sentence from your draft plus one sentence explaining the job of that paragraph. Then respond to a classmate: does the topic sentence actually signal that job?", "posts": [{"name": "Sofia Reyes", "time": "Sep 8 · 2:54 PM", "text": "Topic sentence: “Reliable transit is an access issue, not only a convenience issue.” Job: connect missed buses to attendance and work consequences for riders with fixed schedules.", "replies": [{"name": "Jordan Smith", "time": "Sep 8 · 3:21 PM", "text": "I think it signals the job well because “access” sets up consequences beyond inconvenience. I would expect the evidence to show what riders lose when service is unreliable."}, {"name": "Prof. Jordan Lee", "time": "Sep 8 · 3:48 PM", "text": "Good reader prediction. A strong topic sentence creates an expectation that the paragraph then fulfills."}]}, {"name": "Marcus Bell", "time": "Sep 8 · 5:02 PM", "text": "Mine says “Social media has changed communication.” My job is supposed to be about how algorithmic feeds reward immediate emotional reactions. I think the sentence is too broad.", "replies": [{"name": "Mia Johnson", "time": "Sep 8 · 5:19 PM", "text": "Yeah, I would rewrite it to name algorithmic feeds and the specific behavior you are arguing they encourage."}]}]}]};
