const V7_RECORDINGS={"engr-rec2": {"title": "Recorded Class Excerpt · Decision Matrix Studio", "course": "ENGR 10", "file": "media/engr_week2_decision_matrix.mp4", "date": "Week 2 · Sep 1", "duration": "0:44", "summary": "A fictional recorded-class excerpt reviewing weighted scoring and why sensitivity checks matter.", "chapters": [[0, "Why a matrix is not an answer machine"], [14, "Weighted score example"], [29, "Sensitivity check"]], "transcript": ["Professor: A matrix is useful because it makes your assumptions inspectable. It is not useful if the weights are chosen after you already know which concept you want to win.", "Professor: Multiply each criterion score by its weight, add the totals, then ask what happens if one important assumption moves.", "Professor: If a small weight change flips the winner, say that. The honest conclusion is that the decision is sensitive and needs better evidence."]}, "const-rec2": {"title": "Recorded Class Excerpt · Concrete Takeoff Walkthrough", "course": "CONST 20", "file": "media/const_week2_concrete_takeoff.mp4", "date": "Week 2 · Sep 2", "duration": "0:46", "summary": "A fictional recorded-class excerpt walking from slab dimensions to cubic yards and a documented waste assumption.", "chapters": [[0, "Put every dimension in compatible units"], [16, "Cubic feet to cubic yards"], [31, "Waste and estimate notes"]], "transcript": ["Professor: Four inches is not four feet. Convert thickness before multiplying or the volume will be wrong by a factor of twelve.", "Professor: Once you have cubic feet, divide by 27 for cubic yards. Keep the raw quantity separate from your waste factor.", "Professor: An estimator should be able to see base quantity, waste assumption, rounded purchase quantity, and scope note as separate decisions."]}, "musi-rec3": {"title": "Recorded Musicianship Lab · Intervals → Triads", "course": "MUSI 3A", "file": "media/musi_week3_intervals_triads.mp4", "date": "Week 3 · Sep 7", "duration": "0:45", "summary": "A fictional recorded-class excerpt connecting interval spelling to major/minor triads and tonic–dominant hearing.", "chapters": [[0, "Stack thirds, do not memorize shapes only"], [15, "Major vs minor triad spelling"], [30, "Hear V pulling toward I"]], "transcript": ["Professor: If you already know intervals, triads are not a brand-new universe. A root, third, and fifth are simply stacked interval relationships with correct letter spelling.", "Professor: C–E–G is major because C to E is a major third and C to G is a perfect fifth. Lower E to E-flat and you have C minor.", "Professor: Now listen to G major moving to C major. B is scale degree seven in C and it strongly wants to resolve upward to C. That is part of why dominant-to-tonic feels directional."]}};

function v7Course(id){return BASE_COURSES.find(c=>c.id===id);}
function v7Upsert(arr,item){const i=arr.findIndex(x=>x.id===item.id);if(i>=0)arr[i]=item;else arr.push(item);}
function v7SeedCompleted(c,a){if(!a.completed)return;const k=`${c.id}:${a.id}`;if(!state.submissions[k]?.submitted)state.submissions[k]={submitted:true,answers:a.sampleAnswers||[],fileName:'',submittedAt:a.submittedAt||'Previously submitted',score:a.score??null,feedback:a.feedback||'Graded in this fictional learning simulation.'};}

// Merge the deep original lectures into each course.
const v7LectureCourseMap={engr:'engr10',math:'math1a',phys:'phys4a',ewrt:'ewrt1a',const:'const20',musi:'musi3a'};
if(!v7Course('musi3a')) BASE_COURSES.push(V7_MUSIC_COURSE);
for(const [lid,lecture] of Object.entries(V7_DATA.lectures||{})){const prefix=lid.split('-')[0];const c=v7Course(v7LectureCourseMap[prefix]);if(c){c.lectures=c.lectures||{};c.lectures[lid]=lecture;}}
for(const [cid,list] of Object.entries(V7_ASSIGNMENTS)){const c=v7Course(cid);if(!c)continue;c.assignments=c.assignments||[];for(const a of list){v7Upsert(c.assignments,a);v7SeedCompleted(c,a);}}
for(const [cid,list] of Object.entries(V7_EXTRA_DISCUSSIONS)){const c=v7Course(cid);if(!c)continue;c.discussions=c.discussions||[];for(const d of list)v7Upsert(c.discussions,d);}
for(const [cid,mods] of Object.entries(V7_MODULES)){const c=v7Course(cid);if(c)c.modules=mods;}
const v7Engr=v7Course('engr10'); if(v7Engr){const z=v7Engr.zoomMeetings?.find(x=>x.id==='z2');if(z)z.recordingId='engr-rec2';}
const v7Const=v7Course('const20'); if(v7Const){const z=v7Const.zoomMeetings?.find(x=>x.id==='const-z2');if(z)z.recordingId='const-rec2';}

// Course announcements/messages create the feeling of an active Week 3 without impersonating real people.
if(!ANNOUNCEMENTS.some(a=>a.id==='a-v7-musi')) ANNOUNCEMENTS.unshift({id:'a-v7-musi',course:'MUSI 3A',title:'Week 3: build triads, then hear them',body:'Start with the two original Week 3 lectures. Then use the chord builder and interval trainer before attempting the harmony quiz. The external videos are optional reinforcement, not a substitute for the lesson.',time:'Sep 8, 9:05 AM',target:{course:'musi3a',tab:'modules'}});
if(!ANNOUNCEMENTS.some(a=>a.id==='a-v7-engr')) ANNOUNCEMENTS.unshift({id:'a-v7-engr',course:'ENGR 10',title:'Unit Test 1 review path',body:'Before the unit test, revisit Lecture 3B and the reaction homework. If you miss a knowledge-check item, use the Study Center to reopen that exact lecture.',time:'Sep 8, 4:12 PM',target:{course:'engr10',tab:'study'}});
if(!MESSAGES.some(m=>m.id==='m-v7-musi')) MESSAGES.unshift({id:'m-v7-musi',initials:'SA',from:'Prof. Sofia Alvarez · Fictional',subject:'Week 3 musicianship lab',body:'This week is triads and function. Build the chords on paper, play them, then listen. The recorded excerpt in the module is a short review, not the whole lesson.',time:'Today',unread:true,course:'MUSI 3A'});

