function openRecordedClass(id){
  const r=V7_RECORDINGS[id];if(!r)return toast('Recording unavailable');
  const noteKey=`recording:${id}:note`;
  showModal(`<div class="modal-kicker">${escapeHTML(r.course)} · FICTIONAL RECORDED CLASS SIMULATION</div><h2>${escapeHTML(r.title)}</h2><p class="lead-copy">${escapeHTML(r.summary)}</p><div class="recording-warning">This locally generated video is an original fictional classroom simulation. It is not a real De Anza or Zoom recording.</div><div class="recorded-class-grid"><main><video id="v7RecordedVideo" class="recorded-video" controls preload="metadata"><source src="${r.file}" type="video/mp4">Your browser does not support local MP4 playback.</video><section class="recording-chapters"><h3>Chapters</h3>${r.chapters.map((c,i)=>`<button data-recording-time="${c[0]}"><b>${Math.floor(c[0]/60)}:${String(c[0]%60).padStart(2,'0')}</b><span>${escapeHTML(c[1])}</span></button>`).join('')}</section><section class="recording-transcript"><h3>Teaching notes / transcript excerpt</h3>${r.transcript.map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</section></main><aside><div class="lecture-aside-card"><small>${escapeHTML(r.date)}</small><strong>${escapeHTML(r.duration)}</strong><p>Pause the clip and try the linked lecture/work before continuing.</p></div><label class="assignment-question"><strong>My recording note</strong><textarea id="recordingNote" placeholder="What do I want to remember?">${escapeHTML(state.drafts[noteKey]||'')}</textarea></label><button class="primary-btn full" id="saveRecordingNote">Save note</button></aside></div>`,true);
  const v=document.getElementById('v7RecordedVideo');document.querySelectorAll('[data-recording-time]').forEach(b=>b.onclick=()=>{v.currentTime=Number(b.dataset.recordingTime);v.play().catch(()=>{});});document.getElementById('saveRecordingNote').onclick=()=>{state.drafts[noteKey]=document.getElementById('recordingNote').value;saveState();toast('Recording note saved locally');};addHistory(r.title,r.course);
}

