// ---------- Music practice tools ----------
Object.assign(PRACTICE_LABS,{
 'musi-piano':{title:'Playable Piano · Notes & Chords',type:'musi-piano'},
 'musi-metronome':{title:'Metronome · Pulse & Subdivision',type:'musi-metronome'},
 'musi-interval':{title:'Interval Ear Trainer',type:'musi-interval'},
 'musi-chord':{title:'Chord Builder + Player',type:'musi-chord'}
});
function v7AudioCtx(){window.__v7Audio=window.__v7Audio||new (window.AudioContext||window.webkitAudioContext)();return window.__v7Audio;}
function v7PlayMidi(midi,dur=.55,delay=0,gain=.08){try{const ctx=v7AudioCtx(),o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+delay;o.type='triangle';o.frequency.value=440*Math.pow(2,(midi-69)/12);g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+.015);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+dur+.05);}catch(e){toast('Audio is unavailable in this browser.');}}
function v7PianoHTML(){const notes=[['C4',60],['C#4',61],['D4',62],['D#4',63],['E4',64],['F4',65],['F#4',66],['G4',67],['G#4',68],['A4',69],['A#4',70],['B4',71],['C5',72]];return `<div class="music-tool"><h2>Playable Piano</h2><p>Click notes while reading the lecture. Try spelling a scale or triad instead of only memorizing a visual shape.</p><div class="piano-keys">${notes.map(([n,m])=>`<button class="piano-key ${n.includes('#')?'black-note':''}" data-midi="${m}"><span>${n}</span></button>`).join('')}</div><div class="music-challenge"><strong>Try it</strong><p>Play C–E–G. Then C–Eb–G. Listen to how changing only the third changes the chord quality.</p></div></div>`;}
function v7MetronomeHTML(){return `<div class="music-tool"><h2>Metronome</h2><p>Keep the click as the beat. Clap quarters, then eighths, then a rhythm while the pulse stays unchanged.</p><div class="metronome-panel"><label>BPM <input id="metBpm" type="number" min="40" max="200" value="72"></label><button class="primary-btn" id="metToggle">Start</button><div id="metBeat" class="met-beat">1</div></div><div class="music-challenge"><strong>Practice ladder</strong><ol><li>60 sec quarter notes.</li><li>60 sec eighth-note subdivision.</li><li>Accent only beat 1.</li><li>Mute your counting for 2 measures, then resume and see if you stayed with the click.</li></ol></div></div>`;}
function v7IntervalHTML(){return `<div class="music-tool"><h2>Interval Ear Trainer</h2><p>Listen first. Guess before checking. Then replay and sing the upper note yourself.</p><div class="trainer-panel"><button class="primary-btn" id="newInterval">New interval</button><button class="outline-btn" id="replayInterval">Replay</button><div id="intervalPrompt">Press “New interval.”</div><div class="interval-options">${['Unison','m3','M3','P4','P5','Octave'].map(x=>`<button data-interval-answer="${x}">${x}</button>`).join('')}</div><div id="intervalScore">Score: 0 / 0</div></div><p class="muted">Tip: do not rely only on “happy/sad.” Compare size, stability, and how easily you can sing the top note from the root.</p></div>`;}
function v7ChordHTML(){return `<div class="music-tool"><h2>Chord Builder</h2><p>Choose a root and quality, inspect the pitch classes, then play the sound. The lecture teaches proper letter spelling; this quick audio tool uses sharp-based pitch-class names for convenience.</p><div class="chord-builder"><label>Root <select id="chordRoot">${['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'].map(n=>`<option>${n}</option>`).join('')}</select></label><label>Quality <select id="chordQuality"><option value="maj">Major</option><option value="min">Minor</option><option value="dim">Diminished</option></select></label><button class="primary-btn" id="buildChord">Build & Play</button><div id="chordResult" class="chord-result">C major = C · E · G</div></div><div class="music-challenge"><strong>Applied guitar/keyboard task</strong><p>Build I, IV, V and vi in C major. Play them in at least two orders. Which transitions let one or more notes stay the same?</p></div></div>`;}
let v7MetTimer=null,v7MetCount=0,v7IntervalState={root:60,semi:7,label:'P5',score:0,total:0};
const v7PrevPractice=openPracticeLab;
openPracticeLab=function(id){
 if(!String(id).startsWith('musi-'))return v7PrevPractice(id);
 const p=PRACTICE_LABS[id];let html=id==='musi-piano'?v7PianoHTML():id==='musi-metronome'?v7MetronomeHTML():id==='musi-interval'?v7IntervalHTML():v7ChordHTML();showModal(`<div class="modal-kicker">MUSI 3A · Interactive Practice · UNOFFICIAL DEMO</div>${html}`,true);
 if(id==='musi-piano')document.querySelectorAll('[data-midi]').forEach(b=>b.onclick=()=>v7PlayMidi(Number(b.dataset.midi)));
 if(id==='musi-metronome'){const toggle=document.getElementById('metToggle'),beat=document.getElementById('metBeat');toggle.onclick=()=>{if(v7MetTimer){clearInterval(v7MetTimer);v7MetTimer=null;toggle.textContent='Start';return;}const bpm=Math.max(40,Math.min(200,Number(document.getElementById('metBpm').value)||72));v7MetCount=0;const tick=()=>{v7MetCount=(v7MetCount%4)+1;beat.textContent=v7MetCount;v7PlayMidi(v7MetCount===1?84:79,.08,0,.045);};tick();v7MetTimer=setInterval(tick,60000/bpm);toggle.textContent='Stop';};}
 if(id==='musi-interval'){const choices=[[0,'Unison'],[3,'m3'],[4,'M3'],[5,'P4'],[7,'P5'],[12,'Octave']];const play=()=>{v7PlayMidi(v7IntervalState.root,.45);v7PlayMidi(v7IntervalState.root+v7IntervalState.semi,.55,.55);};document.getElementById('newInterval').onclick=()=>{const x=choices[Math.floor(Math.random()*choices.length)];v7IntervalState.root=60+Math.floor(Math.random()*6);v7IntervalState.semi=x[0];v7IntervalState.label=x[1];document.getElementById('intervalPrompt').textContent='Listen… then choose an interval.';play();};document.getElementById('replayInterval').onclick=play;document.querySelectorAll('[data-interval-answer]').forEach(b=>b.onclick=()=>{v7IntervalState.total++;const ok=b.dataset.intervalAnswer===v7IntervalState.label;if(ok)v7IntervalState.score++;document.getElementById('intervalPrompt').innerHTML=ok?`<strong>Correct · ${escapeHTML(v7IntervalState.label)}</strong>`:`<strong>Not yet.</strong> It was ${escapeHTML(v7IntervalState.label)}. Replay and sing it.`;document.getElementById('intervalScore').textContent=`Score: ${v7IntervalState.score} / ${v7IntervalState.total}`;});}
 if(id==='musi-chord'){document.getElementById('buildChord').onclick=()=>{const names=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'],root=document.getElementById('chordRoot').value,q=document.getElementById('chordQuality').value,ri=names.indexOf(root),ints=q==='maj'?[0,4,7]:q==='min'?[0,3,7]:[0,3,6],notes=ints.map(x=>names[(ri+x)%12]);document.getElementById('chordResult').textContent=`${root} ${q==='maj'?'major':q==='min'?'minor':'diminished'} = ${notes.join(' · ')}`;ints.forEach((x,i)=>v7PlayMidi(60+ri+x,.8,i*.03,.045));};}
 addHistory(p.title,'MUSI 3A');
};

// ---------- Deep lecture renderer ----------
function v7BeamTool(){return `<section class="beam-tool"><div><h3>Interactive Tool · Simply Supported Beam Reactions</h3><p>Use this after the worked example. It solves one downward point load using moment equilibrium about A and vertical-force equilibrium.</p></div><div class="beam-inputs"><label>Beam length L <input id="beamLength" type="number" min="0.1" step="0.1" value="10"><span>ft</span></label><label>Point load P <input id="beamLoad" type="number" min="0" step="10" value="1000"><span>lb</span></label><label>Load position x <input id="beamPosition" type="number" min="0" step="0.1" value="5"><span>ft from A</span></label><button class="primary-btn" id="calcBeam">Calculate reactions</button></div><div id="beamResult" class="beam-result">For L=10 ft, P=1000 lb at x=5 ft: <strong>Ay=500 lb, By=500 lb</strong></div></section>`;}
openLecture=function(c,lectureId){
 const l=c.lectures?.[lectureId];if(!l)return toast('Lecture unavailable');const key=`lecture:${c.id}:${lectureId}`,previous=state.quizChecks[key]||{},progress=state.lectureProgress?.[key]||'';
 const segments=l.segments||((l.sections||[]).map(s=>({title:s[0],paragraphs:[s[1]]})));
 showModal(`<div class="modal-kicker">${escapeHTML(c.code)} · ${escapeHTML(l.week)} · ${escapeHTML(l.duration)}</div><div class="deep-lecture-title"><div><h2>${escapeHTML(l.title)}</h2><p>${escapeHTML(l.intro||'Study the lesson, work the examples, then check your understanding.')}</p></div><span class="status-pill ${progress==='reviewed'?'done':'open'}">${progress==='reviewed'?'Reviewed':'Study lesson'}</span></div><div class="deep-lecture-layout"><main><section class="lecture-objectives"><h3>By the end, you should be able to…</h3><ul>${(l.objectives||[]).map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></section><nav class="lecture-chapter-nav">${segments.map((s,i)=>`<button data-lecture-chapter="${i}">${i+1} · ${escapeHTML(s.title.replace(/^\d+\s*·\s*/,''))}</button>`).join('')}</nav>${segments.map((s,i)=>`<section class="deep-lecture-section" id="lectureChapter${i}"><div class="lecture-num">${i+1}</div><div><h3>${escapeHTML(s.title)}</h3>${(s.paragraphs||[]).map(p=>`<p>${escapeHTML(p)}</p>`).join('')}${s.example?`<div class="teaching-callout example"><b>Worked example</b><p>${escapeHTML(s.example)}</p></div>`:''}${s.pause?`<div class="teaching-callout pause"><b>Pause and try</b><p>${escapeHTML(s.pause)}</p></div>`:''}${s.mistake?`<div class="teaching-callout mistake"><b>Common mistake</b><p>${escapeHTML(s.mistake)}</p></div>`:''}${s.note?`<div class="teaching-callout note"><b>Instructor note</b><p>${escapeHTML(s.note)}</p></div>`:''}</div></section>`).join('')}${lectureId==='engr-l3'?v7BeamTool():''}${(l.recap||[]).length?`<section class="lecture-recap"><h3>Teach it back to yourself</h3><ol>${l.recap.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol></section>`:''}<section class="knowledge-check"><h3>Knowledge Check</h3><p>Guess before looking back. A miss is a pointer to what to review, not a failure.</p>${(l.check||[]).map((q,i)=>`<fieldset><legend>${i+1}. ${escapeHTML(q.q)}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="kc${i}" value="${j}" ${String(previous.answers?.[i])===String(j)?'checked':''}> ${escapeHTML(o)}</label>`).join('')}</fieldset>`).join('')}<button class="primary-btn" id="submitKnowledgeCheck">Check Answers</button><div id="kcResult" class="quiz-result">${previous.score!=null?`Previous score: ${previous.score}/${l.check.length}`:''}</div></section></main><aside class="deep-lecture-aside"><section><h4>Key terms</h4>${(l.keyTerms||[]).map(k=>`<span class="term-chip">${escapeHTML(k)}</span>`).join('')}</section>${(l.resources||[]).length?`<section><h4>Support / second explanations</h4><p class="muted">Use these after the built-in teaching if you want another explanation or more examples.</p><button class="outline-btn full" id="lectureSupport">Open support resources</button></section>`:''}<section><h4>My notebook</h4><textarea id="deepLectureNote" placeholder="Explain one idea in your own words…">${escapeHTML(state.drafts[`${key}:note`]||'')}</textarea><button class="outline-btn full" id="saveDeepLectureNote">Save note</button></section><section class="lecture-progress"><button class="primary-btn full" id="markLectureReviewed">✓ Mark reviewed</button><button class="text-link" id="markLectureRevisit">Flag to revisit</button></section></aside></div>`,true);
 document.querySelectorAll('[data-lecture-chapter]').forEach(b=>b.onclick=()=>document.getElementById(`lectureChapter${b.dataset.lectureChapter}`)?.scrollIntoView({behavior:'smooth',block:'start'}));
 document.getElementById('submitKnowledgeCheck').onclick=()=>{const answers=(l.check||[]).map((_,i)=>document.querySelector(`input[name="kc${i}"]:checked`)?.value??'');const score=(l.check||[]).reduce((n,q,i)=>n+(Number(answers[i])===q.answer?1:0),0);state.quizChecks[key]={answers,score};saveState();document.getElementById('kcResult').innerHTML=`<strong>${score}/${l.check.length} correct.</strong> ${score===l.check.length?'You can move on—or explain the answers aloud to make them stick.':'Reopen the section tied to the missed idea, then try again.'}`;};
 document.getElementById('lectureSupport')?.addEventListener('click',()=>openResources(l.resources||[]));document.getElementById('saveDeepLectureNote').onclick=()=>{state.drafts[`${key}:note`]=document.getElementById('deepLectureNote').value;saveState();toast('Lecture note saved locally');};document.getElementById('markLectureReviewed').onclick=()=>{state.lectureProgress=state.lectureProgress||{};state.lectureProgress[key]='reviewed';saveState();toast('Lecture marked reviewed');};document.getElementById('markLectureRevisit').onclick=()=>{state.lectureProgress=state.lectureProgress||{};state.lectureProgress[key]='revisit';saveState();toast('Lecture flagged for review');};
 const beamBtn=document.getElementById('calcBeam');if(beamBtn)beamBtn.onclick=()=>{const L=Number(document.getElementById('beamLength').value),P=Number(document.getElementById('beamLoad').value),x=Number(document.getElementById('beamPosition').value);if(!(L>0)||P<0||x<0||x>L){document.getElementById('beamResult').innerHTML='<strong>Check the inputs.</strong> x must be between 0 and L.';return;}const By=P*x/L,Ay=P-By;document.getElementById('beamResult').innerHTML=`ΣM_A: By(${L.toFixed(2)}) − ${P.toFixed(1)}(${x.toFixed(2)})=0<br><strong>Ay=${Ay.toFixed(1)} lb up · By=${By.toFixed(1)} lb up</strong><br><small>Check: Ay+By=${(Ay+By).toFixed(1)} lb = applied load.</small>`;};
 addHistory(l.title,c.code);
};

// ---------- Deeper assignment renderer ----------
function v7RenderQuestion(q,i,value=''){return renderQuestion(q,i,value);}
openAssignment=function(c,a){
 if(!a)return;const s=submission(c,a),answers=s.answers||[],submitted=!!s.submitted;
 const why=a.context||'This activity is part of the practice → feedback → relearn cycle for the current module.';
 showModal(`<div class="assignment-header"><div><div class="modal-kicker">${escapeHTML(c.code)} · ${escapeHTML(a.group)}${a.timeLimit?` · ${a.timeLimit} min suggested`:''}</div><h2>${escapeHTML(a.title)}</h2><p>Due ${escapeHTML(a.due)} · ${a.points} points</p></div><div class="status-pill ${submitted?'done':'open'}">${submitted?'Submitted':'Open'}</div></div>${submitted&&s.score!=null?`<div class="feedback-banner"><strong>Score: ${s.score}/${a.points}</strong><span>${escapeHTML(s.feedback||'')}</span><small>Submitted ${escapeHTML(s.submittedAt||'')}</small></div>`:''}<div class="assignment-tabs"><button class="active" data-assignment-tab="details">Learn + Work</button><button data-assignment-tab="rubric">Rubric</button><button data-assignment-tab="submission">${submitted?'Review Submission':'Submit'}</button></div><div id="assignmentTabBody"></div>`,true);
 const renderTab=tab=>{document.querySelectorAll('[data-assignment-tab]').forEach(b=>b.classList.toggle('active',b.dataset.assignmentTab===tab));const body=document.getElementById('assignmentTabBody');
  if(tab==='details')body.innerHTML=`<section class="assignment-learning"><div class="assignment-why"><small>WHY THIS MATTERS</small><p>${escapeHTML(why)}</p></div>${(a.steps||[]).length?`<div><h3>How to approach it</h3><ol>${a.steps.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol></div>`:''}${a.workedExample?`<div class="teaching-callout example"><b>Mini worked example</b><p>${escapeHTML(a.workedExample)}</p></div>`:''}${(a.supportResources||[]).length?`<div class="support-box"><div><strong>Need another explanation?</strong><span>These public resources support the built-in lesson; they do not replace the assignment teaching.</span></div><button class="outline-btn" id="assignmentSupport">Open support</button></div>`:''}</section><div class="rich-copy"><h3>Instructions</h3><p>${escapeHTML(a.instructions||'Complete every question. Show reasoning where the prompt asks for it.')}</p><h3>Work</h3><div class="assignment-work">${a.questions.map((q,i)=>v7RenderQuestion(q,i,answers[i])).join('')}</div>${!submitted?'<button class="primary-btn" id="saveAssignmentDraft">Save Draft</button>':'<p class="muted">Your submitted answers remain available in the Review Submission tab.</p>'}</div>`;
  if(tab==='rubric')body.innerHTML=a.rubric?`<table class="rubric-table"><thead><tr><th>Criterion</th><th>Pts</th><th>What strong work looks like</th></tr></thead><tbody>${a.rubric.map(r=>`<tr><td>${escapeHTML(r[0])}</td><td>${r[1]}</td><td>${escapeHTML(r[2])}</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><h3>${a.kind==='quiz'?'Auto-scored knowledge check':'Completion criteria'}</h3><p>${a.kind==='quiz'?'Each multiple-choice item is equally weighted. Use missed questions to choose what to review.':'Follow the instructions and show your reasoning.'}</p></div>`;
  if(tab==='submission')body.innerHTML=`<div class="rich-copy"><h3>${submitted?'Your submitted work':'Submit your work'}</h3>${submitted&&s.feedback?`<div class="submission-feedback"><b>Instructor feedback · fictional</b><p>${escapeHTML(s.feedback)}</p></div>`:''}<div class="assignment-work">${a.questions.map((q,i)=>v7RenderQuestion(q,i,answers[i])).join('')}</div>${a.kind!=='quiz'?`<label class="file-field"><strong>Optional local attachment</strong><input type="file" id="assignmentFile"><small>${s.fileName?`Previously selected: ${escapeHTML(s.fileName)}`:'Nothing is uploaded to a school or server.'}</small></label>`:''}<div class="submission-actions"><button class="outline-btn" id="saveAssignmentDraft2">Save Draft</button><button class="primary-btn" id="submitAssignment">${submitted?'Resubmit Demo Work':'Submit Assignment'}</button></div>${a.reviewLectureId?`<button class="relearn-button" id="assignmentRelearn">↺ Relearn the connected lecture</button>`:''}</div>`;
  document.getElementById('assignmentSupport')?.addEventListener('click',()=>openResources(a.supportResources||[]));document.getElementById('assignmentRelearn')?.addEventListener('click',()=>openLecture(c,a.reviewLectureId));
  const saveDraft=()=>{const ans=collectAnswers(a);state.submissions[`${c.id}:${a.id}`]={...submission(c,a),answers:ans,submitted:submission(c,a).submitted||false};saveState();toast('Draft saved locally');};document.getElementById('saveAssignmentDraft')?.addEventListener('click',saveDraft);document.getElementById('saveAssignmentDraft2')?.addEventListener('click',saveDraft);
  document.getElementById('submitAssignment')?.addEventListener('click',()=>{const ans=collectAnswers(a);let score=null,feedback='Submitted in the local demo. Use the linked lecture to self-review while fictional feedback is pending.';if(a.kind==='quiz'){let correct=0;a.questions.forEach((q,i)=>{if(Number(ans[i])===q.answer)correct++;});score=Math.round(a.points*(correct/a.questions.length));feedback=`Auto-check: ${correct}/${a.questions.length} correct. ${correct===a.questions.length?'Excellent—now explain one answer without looking.':'Use missed items as a map back to the lecture, then retry.'}`;}const file=document.getElementById('assignmentFile')?.files?.[0],old=submission(c,a);state.submissions[`${c.id}:${a.id}`]={submitted:true,answers:ans,fileName:file?.name||old.fileName||'',submittedAt:new Date().toLocaleString(),score,feedback};saveState();toast('Demo assignment submitted locally');closeModal();renderCourseTab(currentCourseTab);renderDashboard();});
 };
 document.querySelectorAll('[data-assignment-tab]').forEach(b=>b.onclick=()=>renderTab(b.dataset.assignmentTab));renderTab('details');addHistory(a.title,c.code);
};

