renderCalendar=function(){
 const [y,m]=state.calendarMonth.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),start=first.getDay(),events={};const add=(d,text,cid,type='class')=>{events[d]=events[d]||[];events[d].push({text,cid,type});};
 if(y===2026&&m===9){[1,8,15,22,29].forEach(d=>add(d,'ENGR 10 · 6:00–8:30 PM','engr10'));[2,9,16,23,30].forEach(d=>add(d,'CONST 20 · 6:00–8:30 PM','const20'));[7,14,21,28].forEach(d=>add(d,'MUSI 3A · 10:30 AM–12:20 PM','musi3a'));[3,10,17,24].forEach(d=>add(d,'PHYS 4A · Hybrid Lab','phys4a'));add(8,'MUSI: Week 3 harmony module active','musi3a','due');add(9,'ENGR FBD practice due','engr10','due');add(10,'ENGR load-path HW due','engr10','due');add(11,'MUSI triads + PHYS FBD quiz','musi3a','due');add(11,'EWRT paragraph revision','ewrt1a','due');add(12,'ENGR reactions + CONST RFI + PHYS friction','engr10','due');add(12,'MUSI harmony quiz','musi3a','due');add(13,'Unit tests · ENGR / MATH / PHYS / MUSI','musi3a','due');add(13,'CONST Week 3 test + EWRT check','const20','due');}
 if(y===2026&&m===8){[25].forEach(d=>add(d,'ENGR 10 · 6:00–8:30 PM','engr10'));[26].forEach(d=>add(d,'CONST 20 · 6:00–8:30 PM','const20'));[24,31].forEach(d=>add(d,'MUSI 3A · 10:30 AM–12:20 PM','musi3a'));}
 const cells=[];for(let i=0;i<start;i++)cells.push('<div class="calendar-day outside"></div>');for(let d=1;d<=days;d++){const today=y===2026&&m===9&&d===8;cells.push(`<div class="calendar-day ${today?'today':''}"><span class="day-num">${d}</span>${(events[d]||[]).map(e=>`<button class="cal-event ${e.type}" data-cal-course="${e.cid}">${escapeHTML(e.text)}</button>`).join('')}</div>`);}while(cells.length%7)cells.push('<div class="calendar-day outside"></div>');const title=new Date(y,m-1,1).toLocaleString('en-US',{month:'long',year:'numeric'});document.getElementById('calendarGrid').innerHTML=`<div class="calendar-month-title">${title}</div><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar-days">${cells.join('')}</div>`;document.getElementById('calendarSidebar').innerHTML=`<h3>Calendars</h3>${courses().map(c=>`<label><span style="background:${c.color}"></span><input type="checkbox" checked> ${escapeHTML(c.code)}</label>`).join('')}<hr><h3>Week 3 rhythm</h3><p>MUSI 3A: Mon 10:30–12:20<br>ENGR 10: Tue 6:00–8:30<br>CONST 20: Wed 6:00–8:30<br>PHYS 4A: Thu hybrid lab</p>`;document.querySelectorAll('[data-cal-course]').forEach(b=>b.onclick=()=>openCourse(b.dataset.calCourse,b.classList.contains('due')?'assignments':'home'));
};

// Dashboard final polish and Week 3 learning emphasis.
const v7PrevRenderDashboard=renderDashboard;
renderDashboard=function(){v7PrevRenderDashboard();const aside=document.querySelector('.dashboard-aside');if(aside&&!document.getElementById('v7LearningPulse')){const box=document.createElement('section');box.className='aside-section learning-pulse';box.id='v7LearningPulse';box.innerHTML=`<h3>Week 3 Learning Pulse</h3><button data-pulse-course="musi3a"><strong>Music Theory</strong><span>Triads → harmony → ear training</span></button><button data-pulse-course="engr10"><strong>Engineering</strong><span>FBDs → reactions → moments</span></button><button data-pulse-course="const20"><strong>Construction</strong><span>Framing → enclosure → coordination</span></button>`;aside.insertBefore(box,aside.lastElementChild);box.querySelectorAll('[data-pulse-course]').forEach(b=>b.onclick=()=>openCourse(b.dataset.pulseCourse,'modules'));}};

// Add recordings to search without replacing the already broad V6 index until the user searches "recording".
const v7PrevOpenSearch=openSearch;
openSearch=function(){v7PrevOpenSearch();const input=document.getElementById('globalSearchInput'),results=document.getElementById('globalSearchResults');if(!input||!results)return;const original=input.oninput;input.oninput=()=>{original?.();const q=input.value.trim().toLowerCase();if(q.includes('record')||q.includes('zoom video')||q.includes('class video')){for(const [id,r] of Object.entries(V7_RECORDINGS)){const b=document.createElement('button');b.innerHTML=`<strong>${escapeHTML(r.title)}</strong><small>${escapeHTML(r.course)} · Local fictional class recording</small>`;b.onclick=()=>{closeModal();openRecordedClass(id);};results.prepend(b);}}};
};
document.getElementById('searchBtn').onclick=openSearch;

// V7 final identity + save + rerender.
document.title='De Anza College | Unofficial Deep Learning Simulation V7';
document.querySelector('.demo-strip').textContent='UNOFFICIAL FICTIONAL DE ANZA COLLEGE LMS DEMO · DEEP LEARNING EDITION · WEEK 3 · NOT A REAL SCHOOL RECORD, ENROLLMENT, CLASS, CANVAS/ZOOM SITE, OR PROOF OF PARTICIPATION';
saveState();renderNotifications();renderProfile();renderDashboard();renderAllCourses();renderCalendar();renderInbox();renderHistory();setView('dashboard');
